-- Paper I: question bank and report feedback library (Oct 2026 client pack).
-- GENERATED by scripts/generate-paper1-seed.mjs. Do not hand-edit.
--
-- Hard-replaces everything Paper I owns: attempt history, reports, PDF cache rows,
-- class overviews, legacy submissions, questions, groups, dimensions and conversion bands.
-- Do not apply --remote without a D1 backup and an explicit go-ahead.
--
-- Part A keys and target structures come from the MicroFeedback files. They override the
-- question-bank answer tables where the two disagree:
--   01-01-02-007-13: bank B -> A (Tentative Speculation (might not))
--   01-01-02-007-14: bank C -> B (Realistic Present Possibility (may))
--   01-01-02-007-15: bank B -> C (Tentative Speculation (could))
--   01-01-02-007-29: bank C -> B (Present Speculation (may))
--   01-01-06-030-15: bank (none) -> C (Inverted Third Conditional (Formal Inversion))
--
-- feedback_items codes (TT-PP-SS-GGG-QQ-AA):
--   01-01-SS-GGG-QQ-00  grammar-point feedback for one Part A variant (AA 01-04 reserved for option comments)
--   01-01-SS-000-00-AA  area overview: AA 01 = 5/5, 02 = 4/5, 03 = 3-2/5, 04 = 1-0/5
--   01-01-00-000-00-AA  Part A concluding comment: AA 00 = no priority areas, 01 = 1-2, 02 = 3-4, 03 = 5+
--   01-01-00-000-01-AA  Part A linking sentences ({n} = area count, {areas} = area/areas)
--   01-02-00-000-00-AA  Part B placement comment: AA 00 = A2 or below, 01-04 = B1-C2
--   01-02-00-000-01-AA  Part B additional sentence: AA 01 uneven, 02 close, 03 weaker at top, 04 even
--   01-02-00-000-02-AA  Part B roadmap bullets (newline-separated), AA as for placement

-- Wipe Paper I attempt history that would FK-break or silently rebind to new items.
DELETE FROM pdf_cache_index WHERE test_attempt_id IN (SELECT id FROM test_attempts WHERE test_id = (SELECT id FROM tests WHERE test_code = '01'));
DELETE FROM attempt_reports WHERE test_attempt_id IN (SELECT id FROM test_attempts WHERE test_id = (SELECT id FROM tests WHERE test_code = '01'));
DELETE FROM test_attempt_answers WHERE test_attempt_id IN (SELECT id FROM test_attempts WHERE test_id = (SELECT id FROM tests WHERE test_code = '01'));
DELETE FROM test_attempt_answers WHERE question_group_id IN (SELECT id FROM question_groups WHERE test_id = (SELECT id FROM tests WHERE test_code = '01'));
DELETE FROM test_attempts WHERE test_id = (SELECT id FROM tests WHERE test_code = '01');
DELETE FROM class_overviews WHERE test_code = '01';
DELETE FROM submissions;

-- Remove the previous Paper I bank, dimensions and conversion grids.
DELETE FROM questions WHERE question_group_id IN (SELECT id FROM question_groups WHERE test_id = (SELECT id FROM tests WHERE test_code = '01'));
DELETE FROM question_groups WHERE test_id = (SELECT id FROM tests WHERE test_code = '01');
DELETE FROM dimensions WHERE test_part_id IN (SELECT id FROM test_parts WHERE test_id = (SELECT id FROM tests WHERE test_code = '01'));
DELETE FROM score_conversion_bands WHERE test_id = (SELECT id FROM tests WHERE test_code = '01');

-- Schema
ALTER TABLE question_groups ADD COLUMN cefr_level TEXT;
ALTER TABLE score_conversion_bands ADD COLUMN level_label TEXT;
ALTER TABLE attempt_reports DROP COLUMN ai_feedback_zh;
CREATE TABLE feedback_items (
  feedback_code TEXT PRIMARY KEY,
  test_id INTEGER NOT NULL REFERENCES tests(id),
  test_part_id INTEGER REFERENCES test_parts(id),
  question_id INTEGER REFERENCES questions(id),
  kind TEXT NOT NULL,
  type_ref TEXT,
  heading TEXT,
  body TEXT NOT NULL,
  fields_json TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_feedback_items_question ON feedback_items(question_id);
CREATE INDEX idx_feedback_items_kind ON feedback_items(test_id, kind);

