INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (88, '01-02-04-088-10', '10', 'The professor''s lectures were renowned for their __________ style, packed with obscure historical allusions that left novice students thoroughly bewildered.', 'recondite', 'pellucid', 'accessible', 'pragmatic', 'A', 'Obscurity & High-Level Academic Register', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (88, '01-02-04-088-11', '11', 'His speech was an exercise in pure __________; though full of grand rhetoric, it offered no concrete solutions to the fiscal crisis.', 'veracity', 'grandiloquence', 'brevity', 'candor', 'B', 'Rhetorical Style & Discourse Nouns', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (88, '01-02-04-088-12', '12', 'The critic condemned the director''s latest film as a __________ attempt to court commercial success at the expense of artistic integrity.', 'meretricious', 'rigorous', 'profound', 'venerable', 'A', 'Aesthetic & Quality Evaluation Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (88, '01-02-04-088-13', '13', 'The newly appointed CEO moved quickly to __________ the company of its unprofitable overseas subsidiaries.', 'endow', 'augment', 'consolidate', 'divest', 'D', 'Corporate & Asset Management Verbs', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (88, '01-02-04-088-14', '14', 'Her defense of the controversial scientific hypothesis was marked by a __________ logic that dismantled every objection raised by the panel.', 'trenchant', 'specious', 'nebulous', 'feeble', 'A', 'Argumentative Sharpness Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (88, '01-02-04-088-15', '15', 'The board viewed the CFO''s __________ spending habits with growing alarm, noting that luxury expenses were draining company reserves.', 'frugal', 'profligate', 'austere', 'parsimonious', 'B', 'Financial & Expenditure Habit Adjectives', 1760400000000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order, cefr_level) VALUES (89, 1, 2, NULL, NULL, '089', 89, 'B29', 15, 89, 'C2');
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-01', '01', 'Despite the overwhelming empirical evidence presented by climate researchers, a small group of vocal skeptics remained completely __________.', 'recalcitrant', 'compliant', 'malleable', 'acquiescent', 'A', 'Behavior & Resistance Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-02', '02', 'The novel captures the __________ beauty of autumn in New England, reminding readers how fleeting such seasonal moments truly are.', 'immutable', 'perennial', 'ephemeral', 'enduring', 'C', 'Temporal Transience Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-03', '03', 'The judge dismissed the lawsuit, ruling that the plaintiff''s allegations were entirely __________ and lacked any grounding in fact.', 'substantiated', 'baseless', 'pivotal', 'cogent', 'B', 'Legal & Evidentiary Validity Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-04', '04', 'His __________ nature made him a formidable debater, though his aggressive argumentative style often alienated potential political allies.', 'genial', 'pugnacious', 'conciliatory', 'affable', 'B', 'Personality & Dispositive Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-05', '05', 'The company''s financial recovery was aided by an __________ surge in international demand for its specialized semiconductors.', 'adventitious', 'deliberate', 'calculated', 'intrinsic', 'A', 'Cause & Origin Adjectives (adventitious surge)', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-06', '06', 'The author''s prose is notable for its __________ clarity, stripping away all unnecessary ornamentation to deliver stark truth.', 'turgid', 'florid', 'pellucid', 'convoluted', 'C', 'Literary Style & Clarity Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-07', '07', 'The executive board was criticized for its __________ attitude toward emerging market disruptions, failing to act until profits dropped sharply.', 'proactive', 'somnolent', 'vigilant', 'dynamic', 'B', 'Organizational Inaction Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-08', '08', 'The defense attorney sought to __________ the severity of the offense by highlighting the defendant''s prior history of community service.', 'extenuate', 'intensify', 'exacerbate', 'vindicate', 'A', 'Legal Mitigation Verbs (extenuate an offense)', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-09', '09', 'Rather than offering a direct answer, the spokesperson chose to __________ with vague generalities to evade press scrutiny.', 'elucidate', 'tergiversate', 'corroborate', 'articulate', 'B', 'Evasive Rhetoric & Discourse Verbs', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-10', '10', 'The ancient cathedral stands as a testament to the __________ devotion of the medieval artisans who dedicated their lives to its construction.', 'unflagging', 'sporadic', 'desultory', 'fitful', 'A', 'Persistence & Devotion Descriptors', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-11', '11', 'The scholar published an __________ study that meticulously traced the linguistic roots of ancient Indo-European dialects.', 'erudite', 'illiterate', 'superficial', 'unscholarly', 'A', 'Academic Scholarship Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-12', '12', 'The newly appointed chairman inherited an organization plagued by __________ rivalries among senior regional directors.', 'harmonious', 'intestine', 'collaborative', 'unified', 'B', 'Formal/Literary Internal Conflict Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-13', '13', 'The editor recommended removing several __________ paragraphs that detracted from the paper''s central thesis.', 'vital', 'intrinsic', 'supererogatory', 'foundational', 'C', 'Redundancy & Excess Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-14', '14', 'His political strategy was marked by extreme __________; he repeatedly shifted alliances to secure personal power.', 'fidelity', 'perfidy', 'integrity', 'steadfastness', 'B', 'Political Treachery & Betrayal Nouns', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (89, '01-02-04-089-15', '15', 'The general responded to the minor border provocation with __________ force, escalating a localized dispute into a full-scale regional conflict.', 'disproportionate', 'measured', 'moderate', 'restrained', 'A', 'Scale & Response Adjectives', 1760400000000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order, cefr_level) VALUES (90, 1, 2, NULL, NULL, '090', 90, 'B30', 15, 90, 'C2');
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-01', '01', 'The research team''s conclusions were deemed __________ by the editorial board because key experimental controls had been omitted.', 'irrefutable', 'invulnerable', 'vitiated', 'validated', 'C', 'Experimental Integrity & Validity Verbs', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-02', '02', 'The CEO gave a __________ performance at the shareholder meeting, delivering concise data with unwavering authority.', 'magistral', 'hesitant', 'faltering', 'diffident', 'A', 'Authority & Command Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-03', '03', 'The tribunal issued an __________ decree ordering the immediate cessation of all dredging operations along the riverbed.', 'advisory', 'tentative', 'provisional', 'peremptory', 'D', 'Judicial & Command Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-04', '04', 'Her essay offers a __________ reflection on the nature of human mortality, balancing intellectual rigor with deep emotional weight.', 'frivolous', 'poignant', 'trivial', 'shallow', 'B', 'Depth of Feeling & Literary Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-05', '05', 'The diplomat''s __________ skill in handling delicate bilateral discussions prevented what could have been a catastrophic rupture in foreign relations.', 'consumate', 'bungling', 'inept', 'clumsy', 'A', 'High-Level Capability & Skill Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-06', '06', 'The novel''s protagonist is characterized by an __________ desire for wealth that ultimately leads to his personal and social ruin.', 'insatiable', 'indifferent', 'moderate', 'temperate', 'A', 'Desires & Drives Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-07', '07', 'The scientific monograph was praised for its __________ synthesis of disparate theories into a single, elegant framework.', 'fragmented', 'luminous', 'chaotic', 'obscure', 'B', 'Academic Clarity & Style Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-08', '08', 'The minister''s speech was laced with __________ undertones that subtly mocked the opposition''s economic record.', 'sardonic', 'reverent', 'laudatory', 'deferential', 'A', 'Tone & Irony Descriptors', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-09', '09', 'The court ruled that the contract was rendered __________ due to the inclusion of fraudulent financial disclosures.', 'binding', 'valid', 'enforceable', 'null', 'D', 'Legal Validity Adjectives (null and void)', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-10', '10', 'The research paper provided a __________ critique of the prevailing paradigm, exposing severe logical gaps in the literature.', 'complimentary', 'flattering', 'scathing', 'laudatory', 'C', 'Critical Review Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-11', '11', 'The museum curator was praised for her __________ taste in acquiring underappreciated masterpieces for the permanent gallery.', 'discriminating', 'undiscerning', 'indiscriminate', 'uncritical', 'A', 'Aesthetic Judgment Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-12', '12', 'The sudden policy reversal was viewed by political commentators as a desperate attempt to __________ an increasingly hostile electorate.', 'antagonize', 'propitiate', 'incense', 'estrange', 'B', 'Political Appeasement Verbs', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-13', '13', 'The author wrote with a remarkable __________ that laid bare her personal struggles without a trace of self-pity.', 'dissimulation', 'candor', 'duplicity', 'deceit', 'B', 'Honesty & Disclosure Nouns', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-14', '14', 'The CEO maintained an __________ resolve throughout the corporate crisis, guiding the firm safely through bankruptcy proceedings.', 'indomitable', 'irresolute', 'vacillating', 'wavering', 'A', 'Determination & Leadership Adjectives', 1760400000000);
INSERT INTO questions (question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (90, '01-02-04-090-15', '15', 'The tribunal determined that the executive''s actions constituted a __________ breach of fiduciary duty owed to the shareholders.', 'trivial', 'minor', 'flagrant', 'negligible', 'C', 'Legal & Ethical Violation Adjectives', 1760400000000);

-- Report feedback library
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-001-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-001-01'), 'micro_feedback', 'A01-T01', 'Future Perfect Continuous (will have been + -ing)', 'When to use: To show how long an action will have continued up to a point in the future.
Look for: a future time (by December, by the time she arrives) together with a length of time (for ten years, for three hours).
Example: By December, I will have been living here for ten years.
Watch out: Will live and will be living do not show how long something will have continued up to that future point.', '[{"label":"When to use","text":"To show how long an action will have continued up to a point in the future."},{"label":"Look for","text":"a future time (by December, by the time she arrives) together with a length of time (for ten years, for three hours)."},{"label":"Example","text":"By December, I will have been living here for ten years."},{"label":"Watch out","text":"Will live and will be living do not show how long something will have continued up to that future point."}]', 101);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-001-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-001-02'), 'micro_feedback', 'A01-T02', 'Future Continuous (will be + -ing)', 'When to use: To describe an action that will be in progress at a particular time in the future.
Look for: a specific future time (at 8 p.m. tonight, this time next week) or a time clause (when you arrive).
Example: At 8 o’clock tonight, I will be studying for my Spanish test.
Watch out: Do not add been (will have been + -ing) unless the sentence tells you how long the action will have lasted (for three hours).', '[{"label":"When to use","text":"To describe an action that will be in progress at a particular time in the future."},{"label":"Look for","text":"a specific future time (at 8 p.m. tonight, this time next week) or a time clause (when you arrive)."},{"label":"Example","text":"At 8 o’clock tonight, I will be studying for my Spanish test."},{"label":"Watch out","text":"Do not add been (will have been + -ing) unless the sentence tells you how long the action will have lasted (for three hours)."}]', 102);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-001-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-001-03'), 'micro_feedback', 'A01-T01', 'Future Perfect Continuous (will have been + -ing)', 'When to use: To show how long an action will have continued up to a point in the future.
