INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-003-23-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-003-23'), 'micro_feedback', 'A01-T09', 'Present Perfect (has/have + past participle)', 'When to use: For past actions that matter now, life experiences, and situations that started in the past and continue now.
Look for: already, yet, ever, never, just, recently, so far, since 2020, for three years.
Example: The department has updated the curriculum to meet new standards.
Watch out: Do not use it with a finished past time such as yesterday or last week: I finished the report yesterday, not I have finished the report yesterday.', '[{"label":"When to use","text":"For past actions that matter now, life experiences, and situations that started in the past and continue now."},{"label":"Look for","text":"already, yet, ever, never, just, recently, so far, since 2020, for three years."},{"label":"Example","text":"The department has updated the curriculum to meet new standards."},{"label":"Watch out","text":"Do not use it with a finished past time such as yesterday or last week: I finished the report yesterday, not I have finished the report yesterday."}]', 323);
