INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-004-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-004-01'), 'micro_feedback', 'A01-T11', 'Simple Present for timetables', 'When to use: For future events fixed by a timetable or an official schedule.
Look for: verbs such as leave, arrive, start, open and close, with a fixed time (at 9 a.m., on Monday).
Example: The conference starts at 9 a.m. tomorrow.
Watch out: For timetables and schedules, the simple present is usually more natural than will: The train leaves at 5 p.m.', '[{"label":"When to use","text":"For future events fixed by a timetable or an official schedule."},{"label":"Look for","text":"verbs such as leave, arrive, start, open and close, with a fixed time (at 9 a.m., on Monday)."},{"label":"Example","text":"The conference starts at 9 a.m. tomorrow."},{"label":"Watch out","text":"For timetables and schedules, the simple present is usually more natural than will: The train leaves at 5 p.m."}]', 401);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-004-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-004-02'), 'micro_feedback', 'A01-T13', 'Be going to', 'When to use: For plans or intentions decided before speaking, and for predictions based on what you can see now.
Look for: evidence such as Look at those clouds! or Watch out!, or a plan already made (I’ve decided to…).
Example: Look at those dark clouds. It is going to rain.
Watch out: When there is clear evidence right now, be going to is more natural than will: Be careful – he’s going to fall!', '[{"label":"When to use","text":"For plans or intentions decided before speaking, and for predictions based on what you can see now."},{"label":"Look for","text":"evidence such as Look at those clouds! or Watch out!, or a plan already made (I’ve decided to…)."},{"label":"Example","text":"Look at those dark clouds. It is going to rain."},{"label":"Watch out","text":"When there is clear evidence right now, be going to is more natural than will: Be careful – he’s going to fall!"}]', 402);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-004-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-004-03'), 'micro_feedback', 'A01-T12', 'Present Continuous for arrangements', 'When to use: For personal plans that have already been arranged, usually with a fixed time, place or other people.
Look for: verbs such as meet, visit, fly, stay and have dinner, with a future time (this Friday, next weekend).
Example: I am meeting the academic committee this Friday.
Watch out: The simple present is mainly used for public timetables. For your own arrangements, I’m flying to London tomorrow is more natural than I fly to London tomorrow.', '[{"label":"When to use","text":"For personal plans that have already been arranged, usually with a fixed time, place or other people."},{"label":"Look for","text":"verbs such as meet, visit, fly, stay and have dinner, with a future time (this Friday, next weekend)."},{"label":"Example","text":"I am meeting the academic committee this Friday."},{"label":"Watch out","text":"The simple present is mainly used for public timetables. For your own arrangements, I’m flying to London tomorrow is more natural than I fly to London tomorrow."}]', 403);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-004-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-004-04'), 'micro_feedback', 'A01-T14', 'Will / won’t', 'When to use: For decisions made at the moment of speaking, offers, promises, and predictions based on opinion rather than evidence.
Look for: I think, probably, I’m sure, I promise, and sudden decisions (The phone’s ringing!).
Example: I think the new policy will improve student engagement.
Watch out: Use will for a decision you make on the spot and be going to for a plan you had already made: The phone’s ringing – I’ll get it.', '[{"label":"When to use","text":"For decisions made at the moment of speaking, offers, promises, and predictions based on opinion rather than evidence."},{"label":"Look for","text":"I think, probably, I’m sure, I promise, and sudden decisions (The phone’s ringing!)."},{"label":"Example","text":"I think the new policy will improve student engagement."},{"label":"Watch out","text":"Use will for a decision you make on the spot and be going to for a plan you had already made: The phone’s ringing – I’ll get it."}]', 404);
