INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-01-005-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-01-005-06'), 'micro_feedback', 'A01-T10', 'Present Perfect Continuous (has/have been + -ing)', 'When to use: To focus on how long an activity has been going on from the past until now, or on an activity that has just stopped and still has visible results.
Look for: for six hours, all morning, since 8 a.m., lately, recently.
Example: The board has been reviewing the reports all morning.
Watch out: When the focus is on a result or on how many things are finished, use has/have + past participle: She has written three reports, not She has been writing three reports.', '[{"label":"When to use","text":"To focus on how long an activity has been going on from the past until now, or on an activity that has just stopped and still has visible results."},{"label":"Look for","text":"for six hours, all morning, since 8 a.m., lately, recently."},{"label":"Example","text":"The board has been reviewing the reports all morning."},{"label":"Watch out","text":"When the focus is on a result or on how many things are finished, use has/have + past participle: She has written three reports, not She has been writing three reports."}]', 506);
