INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-02-006-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-02-006-01'), 'micro_feedback', 'A02-T01', 'Being sure about the present (must / can’t + base verb)', 'When to use: To make a confident conclusion about a present situation, based on the evidence you have.
Key difference: must = you are sure something is true; can’t (or couldn’t) = you are sure something is not true.
Look for: clues that act as evidence (The lights are still on…, He left an hour ago…, She has worked for 12 hours…).
Examples: The lab lights are still on, so Professor Chan must be in her office. He left an hour ago, so he can’t be in the meeting room now.
Watch out: The opposite of must here is can’t, not mustn’t. Mustn’t means “not allowed”: That can’t be true, not That mustn’t be true.', '[{"label":"When to use","text":"To make a confident conclusion about a present situation, based on the evidence you have."},{"label":"Key difference","text":"must = you are sure something is true; can’t (or couldn’t) = you are sure something is not true."},{"label":"Look for","text":"clues that act as evidence (The lights are still on…, He left an hour ago…, She has worked for 12 hours…)."},{"label":"Examples","text":"The lab lights are still on, so Professor Chan must be in her office. He left an hour ago, so he can’t be in the meeting room now."},{"label":"Watch out","text":"The opposite of must here is can’t, not mustn’t. Mustn’t means “not allowed”: That can’t be true, not That mustn’t be true."}]', 601);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-02-006-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-02-006-02'), 'micro_feedback', 'A02-T01', 'Being sure about the present (must / can’t + base verb)', 'When to use: To make a confident conclusion about a present situation, based on the evidence you have.
Key difference: must = you are sure something is true; can’t (or couldn’t) = you are sure something is not true.
Look for: clues that act as evidence (The lights are still on…, He left an hour ago…, She has worked for 12 hours…).
Examples: The lab lights are still on, so Professor Chan must be in her office. He left an hour ago, so he can’t be in the meeting room now.
Watch out: The opposite of must here is can’t, not mustn’t. Mustn’t means “not allowed”: That can’t be true, not That mustn’t be true.', '[{"label":"When to use","text":"To make a confident conclusion about a present situation, based on the evidence you have."},{"label":"Key difference","text":"must = you are sure something is true; can’t (or couldn’t) = you are sure something is not true."},{"label":"Look for","text":"clues that act as evidence (The lights are still on…, He left an hour ago…, She has worked for 12 hours…)."},{"label":"Examples","text":"The lab lights are still on, so Professor Chan must be in her office. He left an hour ago, so he can’t be in the meeting room now."},{"label":"Watch out","text":"The opposite of must here is can’t, not mustn’t. Mustn’t means “not allowed”: That can’t be true, not That mustn’t be true."}]', 602);
