INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-02-009-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-02-009-06'), 'micro_feedback', 'A02-T05', 'Rules and obligations (must, have to, mustn’t, don’t have to)', 'When to use: To say what is necessary, what is not allowed, and what is not necessary.
Key difference: must / have to / need to / be required to = it is necessary; mustn’t = it is not allowed; don’t have to / don’t need to = it is not necessary, but you can if you want.
Look for: rules, laws, deadlines and official instructions (by law, all staff, before the deadline).
Examples: All visitors must sign in at reception. You don’t have to bring a laptop; computers are provided.
Watch out: Mustn’t and don’t have to have very different meanings: You mustn’t use your phone (it is not allowed) vs. You don’t have to use your phone (it is not necessary).', '[{"label":"When to use","text":"To say what is necessary, what is not allowed, and what is not necessary."},{"label":"Key difference","text":"must / have to / need to / be required to = it is necessary; mustn’t = it is not allowed; don’t have to / don’t need to = it is not necessary, but you can if you want."},{"label":"Look for","text":"rules, laws, deadlines and official instructions (by law, all staff, before the deadline)."},{"label":"Examples","text":"All visitors must sign in at reception. You don’t have to bring a laptop; computers are provided."},{"label":"Watch out","text":"Mustn’t and don’t have to have very different meanings: You mustn’t use your phone (it is not allowed) vs. You don’t have to use your phone (it is not necessary)."}]', 906);
