INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-01'), 'micro_feedback', 'A03-T03', 'Showing possession (whose + noun)', 'When to use: To show that something belongs to or is connected with the person or thing just mentioned. Whose replaces his, her, its or their.
Look for: a noun straight after the relative word (a neighbour whose dog…, a company whose profits…).
Example: I helped a neighbour whose dog ran away during the storm.
Watch out: Whose shows possession; who’s means who is or who has: the friend whose car broke down, not the friend who’s car broke down.', '[{"label":"When to use","text":"To show that something belongs to or is connected with the person or thing just mentioned. Whose replaces his, her, its or their."},{"label":"Look for","text":"a noun straight after the relative word (a neighbour whose dog…, a company whose profits…)."},{"label":"Example","text":"I helped a neighbour whose dog ran away during the storm."},{"label":"Watch out","text":"Whose shows possession; who’s means who is or who has: the friend whose car broke down, not the friend who’s car broke down."}]', 1101);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-02'), 'micro_feedback', 'A03-T02', 'Relative pronouns as the object (who(m), which, that, or no pronoun)', 'When to use: When the relative pronoun is the object of the clause, so it is followed by a new subject and verb.
Key difference: who / whom / that = people (whom is more common in formal writing); which / that = things. You can also leave the pronoun out.
Look for: a relative pronoun followed by a subject and verb (the barista whom I talked to).
Example: The barista whom I talked to this morning was very friendly.
Watch out: Do not repeat the object at the end: the shirt that I bought, not the shirt that I bought it.', '[{"label":"When to use","text":"When the relative pronoun is the object of the clause, so it is followed by a new subject and verb."},{"label":"Key difference","text":"who / whom / that = people (whom is more common in formal writing); which / that = things. You can also leave the pronoun out."},{"label":"Look for","text":"a relative pronoun followed by a subject and verb (the barista whom I talked to)."},{"label":"Example","text":"The barista whom I talked to this morning was very friendly."},{"label":"Watch out","text":"Do not repeat the object at the end: the shirt that I bought, not the shirt that I bought it."}]', 1102);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-03'), 'micro_feedback', 'A03-T01', 'Relative pronouns as the subject (who, which, that)', 'When to use: When the relative pronoun is the subject of the clause, so it is followed directly by a verb.
