INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-06'), 'micro_feedback', 'A03-T03', 'Showing possession (whose + noun)', 'When to use: To show that something belongs to or is connected with the person or thing just mentioned. Whose replaces his, her, its or their.
Look for: a noun straight after the relative word (a neighbour whose dog…, a company whose profits…).
Example: I helped a neighbour whose dog ran away during the storm.
Watch out: Whose shows possession; who’s means who is or who has: the friend whose car broke down, not the friend who’s car broke down.', '[{"label":"When to use","text":"To show that something belongs to or is connected with the person or thing just mentioned. Whose replaces his, her, its or their."},{"label":"Look for","text":"a noun straight after the relative word (a neighbour whose dog…, a company whose profits…)."},{"label":"Example","text":"I helped a neighbour whose dog ran away during the storm."},{"label":"Watch out","text":"Whose shows possession; who’s means who is or who has: the friend whose car broke down, not the friend who’s car broke down."}]', 1106);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-07'), 'micro_feedback', 'A03-T04', 'Preposition + whom / which', 'When to use: When a preposition comes before the relative pronoun, including phrases such as one of whom and the roof of which.
Key difference: whom = people; which = things.
Look for: a preposition directly before the gap (to ___, with ___, from ___, one of ___).
Examples: The agency from which we booked our tickets gave us a full refund. She bought five old books, two of which were signed by the author.
Watch out: After a preposition, do not use who, that or it: one of which was red, not one of that was red.', '[{"label":"When to use","text":"When a preposition comes before the relative pronoun, including phrases such as one of whom and the roof of which."},{"label":"Key difference","text":"whom = people; which = things."},{"label":"Look for","text":"a preposition directly before the gap (to ___, with ___, from ___, one of ___)."},{"label":"Examples","text":"The agency from which we booked our tickets gave us a full refund. She bought five old books, two of which were signed by the author."},{"label":"Watch out","text":"After a preposition, do not use who, that or it: one of which was red, not one of that was red."}]', 1107);
