INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-29-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-29'), 'micro_feedback', 'A03-T01', 'Relative pronouns as the subject (who, which, that)', 'When to use: When the relative pronoun is the subject of the clause, so it is followed directly by a verb.
Key difference: who / that = people (who is more common in formal writing); which / that = things and animals.
Look for: a relative pronoun followed immediately by a verb (a mechanic who charges…).
Example: I know a mechanic who charges fair prices.
Watch out: Do not add another subject: the neighbour who lives next door, not the neighbour who he lives next door.', '[{"label":"When to use","text":"When the relative pronoun is the subject of the clause, so it is followed directly by a verb."},{"label":"Key difference","text":"who / that = people (who is more common in formal writing); which / that = things and animals."},{"label":"Look for","text":"a relative pronoun followed immediately by a verb (a mechanic who charges…)."},{"label":"Example","text":"I know a mechanic who charges fair prices."},{"label":"Watch out","text":"Do not add another subject: the neighbour who lives next door, not the neighbour who he lives next door."}]', 1129);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-011-30-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-011-30'), 'micro_feedback', 'A03-T04', 'Preposition + whom / which', 'When to use: When a preposition comes before the relative pronoun, including phrases such as one of whom and the roof of which.
Key difference: whom = people; which = things.
Look for: a preposition directly before the gap (to ___, with ___, from ___, one of ___).
Examples: The agency from which we booked our tickets gave us a full refund. She bought five old books, two of which were signed by the author.
Watch out: After a preposition, do not use who, that or it: one of which was red, not one of that was red.', '[{"label":"When to use","text":"When a preposition comes before the relative pronoun, including phrases such as one of whom and the roof of which."},{"label":"Key difference","text":"whom = people; which = things."},{"label":"Look for","text":"a preposition directly before the gap (to ___, with ___, from ___, one of ___)."},{"label":"Examples","text":"The agency from which we booked our tickets gave us a full refund. She bought five old books, two of which were signed by the author."},{"label":"Watch out","text":"After a preposition, do not use who, that or it: one of which was red, not one of that was red."}]', 1130);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-012-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-012-01'), 'micro_feedback', 'A03-T05', 'Essential or extra information (with or without commas)', 'When to use: Use a clause without commas when it tells us which person or thing you mean. Use commas when the clause only adds extra information about someone or something already clear.
Look for: whether the noun is already clear (my mother, London, the Moon, a name) or still needs to be identified (the man, a laptop).
Examples: The restaurant that serves spicy noodles is always busy. (Which restaurant?) My brother, who lives in Manchester, is visiting us. (Extra information.)
Watch out: Do not use that after a comma. Use who for people and which for things: My car, which is ten years old, still works, not My car, that is ten years old….', '[{"label":"When to use","text":"Use a clause without commas when it tells us which person or thing you mean. Use commas when the clause only adds extra information about someone or something already clear."},{"label":"Look for","text":"whether the noun is already clear (my mother, London, the Moon, a name) or still needs to be identified (the man, a laptop)."},{"label":"Examples","text":"The restaurant that serves spicy noodles is always busy. (Which restaurant?) My brother, who lives in Manchester, is visiting us. (Extra information.)"},{"label":"Watch out","text":"Do not use that after a comma. Use who for people and which for things: My car, which is ten years old, still works, not My car, that is ten years old…."}]', 1201);
