INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-013-28-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-013-28'), 'micro_feedback', 'A03-T01', 'Relative pronouns as the subject (who, which, that)', 'When to use: When the relative pronoun is the subject of the clause, so it is followed directly by a verb.
Key difference: who / that = people (who is more common in formal writing); which / that = things and animals.
Look for: a relative pronoun followed immediately by a verb (a mechanic who charges…).
Example: I know a mechanic who charges fair prices.
Watch out: Do not add another subject: the neighbour who lives next door, not the neighbour who he lives next door.', '[{"label":"When to use","text":"When the relative pronoun is the subject of the clause, so it is followed directly by a verb."},{"label":"Key difference","text":"who / that = people (who is more common in formal writing); which / that = things and animals."},{"label":"Look for","text":"a relative pronoun followed immediately by a verb (a mechanic who charges…)."},{"label":"Example","text":"I know a mechanic who charges fair prices."},{"label":"Watch out","text":"Do not add another subject: the neighbour who lives next door, not the neighbour who he lives next door."}]', 1328);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-013-29-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-013-29'), 'micro_feedback', 'A03-T02', 'Relative pronouns as the object (who(m), which, that, or no pronoun)', 'When to use: When the relative pronoun is the object of the clause, so it is followed by a new subject and verb.
Key difference: who / whom / that = people (whom is more common in formal writing); which / that = things. You can also leave the pronoun out.
Look for: a relative pronoun followed by a subject and verb (the barista whom I talked to).
Example: The barista whom I talked to this morning was very friendly.
Watch out: Do not repeat the object at the end: the shirt that I bought, not the shirt that I bought it.', '[{"label":"When to use","text":"When the relative pronoun is the object of the clause, so it is followed by a new subject and verb."},{"label":"Key difference","text":"who / whom / that = people (whom is more common in formal writing); which / that = things. You can also leave the pronoun out."},{"label":"Look for","text":"a relative pronoun followed by a subject and verb (the barista whom I talked to)."},{"label":"Example","text":"The barista whom I talked to this morning was very friendly."},{"label":"Watch out","text":"Do not repeat the object at the end: the shirt that I bought, not the shirt that I bought it."}]', 1329);
