INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-015-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-015-01'), 'micro_feedback', 'A03-T13', 'Shorter clauses with past participles (-ed / third form)', 'When to use: To shorten a relative clause when something is done to the noun. Remove who / which / that and is / are / was, and keep the past participle.
Look for: a noun that receives the action, often with by or a time (the policy approved yesterday, a house built in 1900).
Example: Parcels left on the doorstep will be collected by the driver. (= Parcels that are left…)
Watch out: Use -ing when the noun does the action and the past participle when something is done to it: the document signed by the director, not the document signing by the director.', '[{"label":"When to use","text":"To shorten a relative clause when something is done to the noun. Remove who / which / that and is / are / was, and keep the past participle."},{"label":"Look for","text":"a noun that receives the action, often with by or a time (the policy approved yesterday, a house built in 1900)."},{"label":"Example","text":"Parcels left on the doorstep will be collected by the driver. (= Parcels that are left…)"},{"label":"Watch out","text":"Use -ing when the noun does the action and the past participle when something is done to it: the document signed by the director, not the document signing by the director."}]', 1501);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-015-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-015-02'), 'micro_feedback', 'A03-T12', 'Shorter clauses with -ing', 'When to use: To shorten a relative clause when the noun is doing the action. Remove who / which / that (and is / are / was) and use the -ing form.
Look for: a noun followed by an action that it is doing (the man standing…, the bus carrying…).
Example: The bus carrying students to school arrived late. (= The bus that was carrying students…)
Watch out: Without who / which / that, the verb must be in the -ing form: the woman living next door, not the woman lives next door.', '[{"label":"When to use","text":"To shorten a relative clause when the noun is doing the action. Remove who / which / that (and is / are / was) and use the -ing form."},{"label":"Look for","text":"a noun followed by an action that it is doing (the man standing…, the bus carrying…)."},{"label":"Example","text":"The bus carrying students to school arrived late. (= The bus that was carrying students…)"},{"label":"Watch out","text":"Without who / which / that, the verb must be in the -ing form: the woman living next door, not the woman lives next door."}]', 1502);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-03-015-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-03-015-03'), 'micro_feedback', 'A03-T14', 'Shorter clauses with to + verb', 'When to use: After the first, the last, the only, the next or the best, and to describe what someone needs to do or can do (a book to read, rules to follow).
Look for: words such as the first, the second, the last and the only, or a noun followed by a task or purpose.
Examples: He was the only applicant to pass the interview. There are three rules to follow.
Watch out: After the first, the last or the only, use to + verb, not -ing: the first person to land on the Moon, not the first person landing on the Moon.', '[{"label":"When to use","text":"After the first, the last, the only, the next or the best, and to describe what someone needs to do or can do (a book to read, rules to follow)."},{"label":"Look for","text":"words such as the first, the second, the last and the only, or a noun followed by a task or purpose."},{"label":"Examples","text":"He was the only applicant to pass the interview. There are three rules to follow."},{"label":"Watch out","text":"After the first, the last or the only, use to + verb, not -ing: the first person to land on the Moon, not the first person landing on the Moon."}]', 1503);
