INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-016-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-016-01'), 'micro_feedback', 'A04-T02', 'that-clauses as the subject (That he lied…)', 'When to use: When a whole statement is the subject of the sentence, at the start before the main verb.
Look for: a sentence that starts with a full idea and then has a main verb such as is, was or surprised.
Example: That the shop closed so suddenly surprised everyone.
Watch out: You can sometimes drop that after a verb, but never at the start of a sentence: That she won was a surprise, not She won was a surprise.', '[{"label":"When to use","text":"When a whole statement is the subject of the sentence, at the start before the main verb."},{"label":"Look for","text":"a sentence that starts with a full idea and then has a main verb such as is, was or surprised."},{"label":"Example","text":"That the shop closed so suddenly surprised everyone."},{"label":"Watch out","text":"You can sometimes drop that after a verb, but never at the start of a sentence: That she won was a surprise, not She won was a surprise."}]', 1601);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-016-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-016-02'), 'micro_feedback', 'A04-T04', 'that-clauses after be (The problem is that…)', 'When to use: After is or was to explain what a problem, reason or truth is.
Look for: The reason is…, The problem was…, The truth is… followed by a full statement.
Example: The reason for the delay was that the train broke down.
Watch out: Formal English prefers that after The reason is: The reason is that it rained rather than The reason is because it rained.', '[{"label":"When to use","text":"After is or was to explain what a problem, reason or truth is."},{"label":"Look for","text":"The reason is…, The problem was…, The truth is… followed by a full statement."},{"label":"Example","text":"The reason for the delay was that the train broke down."},{"label":"Watch out","text":"Formal English prefers that after The reason is: The reason is that it rained rather than The reason is because it rained."}]', 1602);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-016-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-016-03'), 'micro_feedback', 'A04-T03', 'that-clauses after nouns (the fact that…, the news that…)', 'When to use: After nouns such as fact, news, belief, rumour and suggestion, to explain what the fact or news actually is.
Look for: one of these nouns followed by a complete statement.
Example: The news that she got the job made us very happy.
Watch out: Use that, not which, when the clause tells you what the news or fact is: the news that she won, not the news which she won.', '[{"label":"When to use","text":"After nouns such as fact, news, belief, rumour and suggestion, to explain what the fact or news actually is."},{"label":"Look for","text":"one of these nouns followed by a complete statement."},{"label":"Example","text":"The news that she got the job made us very happy."},{"label":"Watch out","text":"Use that, not which, when the clause tells you what the news or fact is: the news that she won, not the news which she won."}]', 1603);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-016-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-016-04'), 'micro_feedback', 'A04-T01', 'that-clauses after verbs (explain that…, told me that…)', 'When to use: After verbs of saying, thinking and noticing (explain, mention, notice, warn, assure) to report a complete statement.
Look for: a reporting or thinking verb followed by a full idea with its own subject and verb.
Example: The guide explained that the museum closes at five.
Watch out: Use that for a complete statement and what only when something is missing: She knows that he lied, not She knows what he lied.', '[{"label":"When to use","text":"After verbs of saying, thinking and noticing (explain, mention, notice, warn, assure) to report a complete statement."},{"label":"Look for","text":"a reporting or thinking verb followed by a full idea with its own subject and verb."},{"label":"Example","text":"The guide explained that the museum closes at five."},{"label":"Watch out","text":"Use that for a complete statement and what only when something is missing: She knows that he lied, not She knows what he lied."}]', 1604);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-016-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-016-05'), 'micro_feedback', 'A04-T02', 'that-clauses as the subject (That he lied…)', 'When to use: When a whole statement is the subject of the sentence, at the start before the main verb.
Look for: a sentence that starts with a full idea and then has a main verb such as is, was or surprised.
Example: That the shop closed so suddenly surprised everyone.
Watch out: You can sometimes drop that after a verb, but never at the start of a sentence: That she won was a surprise, not She won was a surprise.', '[{"label":"When to use","text":"When a whole statement is the subject of the sentence, at the start before the main verb."},{"label":"Look for","text":"a sentence that starts with a full idea and then has a main verb such as is, was or surprised."},{"label":"Example","text":"That the shop closed so suddenly surprised everyone."},{"label":"Watch out","text":"You can sometimes drop that after a verb, but never at the start of a sentence: That she won was a surprise, not She won was a surprise."}]', 1605);
