INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-016-30-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-016-30'), 'micro_feedback', 'A04-T04', 'that-clauses after be (The problem is that…)', 'When to use: After is or was to explain what a problem, reason or truth is.
Look for: The reason is…, The problem was…, The truth is… followed by a full statement.
Example: The reason for the delay was that the train broke down.
Watch out: Formal English prefers that after The reason is: The reason is that it rained rather than The reason is because it rained.', '[{"label":"When to use","text":"After is or was to explain what a problem, reason or truth is."},{"label":"Look for","text":"The reason is…, The problem was…, The truth is… followed by a full statement."},{"label":"Example","text":"The reason for the delay was that the train broke down."},{"label":"Watch out","text":"Formal English prefers that after The reason is: The reason is that it rained rather than The reason is because it rained."}]', 1630);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-017-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-017-01'), 'micro_feedback', 'A04-T07', 'Indirect wh- questions (word order)', 'When to use: When a wh- question (what, where, how, why, which) sits inside a longer sentence (Do you know where…?, Tell me what…).
Look for: a question word in the middle of a sentence. After it, use normal statement order: subject + verb.
Examples: Could you tell me where the station is? I don''t know what time the film starts.
Watch out: Do not use question order or do / does / did: I wonder where he is, not I wonder where is he; what she wants, not what does she want.', '[{"label":"When to use","text":"When a wh- question (what, where, how, why, which) sits inside a longer sentence (Do you know where…?, Tell me what…)."},{"label":"Look for","text":"a question word in the middle of a sentence. After it, use normal statement order: subject + verb."},{"label":"Examples","text":"Could you tell me where the station is? I don''t know what time the film starts."},{"label":"Watch out","text":"Do not use question order or do / does / did: I wonder where he is, not I wonder where is he; what she wants, not what does she want."}]', 1701);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-017-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-017-02'), 'micro_feedback', 'A04-T05', 'Indirect yes/no questions (whether / if)', 'When to use: To include a yes/no question inside a longer sentence (I wonder whether…, Ask if…).
Key difference: if and whether are often both possible, but only whether works after a preposition or at the start of a sentence.
Look for: a preposition (about, on) or a sentence start before the gap.
Example: It depends on whether it rains tomorrow.
Watch out: It depends on whether it rains, not It depends on if it rains.', '[{"label":"When to use","text":"To include a yes/no question inside a longer sentence (I wonder whether…, Ask if…)."},{"label":"Key difference","text":"if and whether are often both possible, but only whether works after a preposition or at the start of a sentence."},{"label":"Look for","text":"a preposition (about, on) or a sentence start before the gap."},{"label":"Example","text":"It depends on whether it rains tomorrow."},{"label":"Watch out","text":"It depends on whether it rains, not It depends on if it rains."}]', 1702);
