INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-017-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-017-04'), 'micro_feedback', 'A04-T06', 'Choices with whether… or / whether or not', 'When to use: To report a question that offers a choice between two options.
Look for: or or or not later in the sentence, or or not straight after the gap.
Example: We discussed whether or not to cancel the trip.
Watch out: Use whether, not if, directly before or not: whether or not to go, not if or not to go.', '[{"label":"When to use","text":"To report a question that offers a choice between two options."},{"label":"Look for","text":"or or or not later in the sentence, or or not straight after the gap."},{"label":"Example","text":"We discussed whether or not to cancel the trip."},{"label":"Watch out","text":"Use whether, not if, directly before or not: whether or not to go, not if or not to go."}]', 1704);
