INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-018-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-018-01'), 'micro_feedback', 'A04-T08', 'Reported speech: changing the tense', 'When to use: When you report what someone said using a past verb (said, told, explained).
Look for: a past reporting verb. Move the tense one step back: is → was, will → would, has done → had done, must / have to → had to.
Example: She said, ‘I will call you.’ → She said that she would call me.
Watch out: Do not keep will or a present tense after said unless it is a general truth: She said she would call, not She said she will call.', '[{"label":"When to use","text":"When you report what someone said using a past verb (said, told, explained)."},{"label":"Look for","text":"a past reporting verb. Move the tense one step back: is → was, will → would, has done → had done, must / have to → had to."},{"label":"Example","text":"She said, ‘I will call you.’ → She said that she would call me."},{"label":"Watch out","text":"Do not keep will or a present tense after said unless it is a general truth: She said she would call, not She said she will call."}]', 1801);
