INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-04-019-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-04-019-01'), 'micro_feedback', 'A04-T09', 'The base verb after suggest that, essential that (subjunctive)', 'When to use: After verbs and adjectives of advising, requesting or necessity (suggest, insist, recommend, it is essential / vital that…).
Look for: one of these words + that. The next verb stays in its base form for every subject: he take, it be repaired, they not be late.
Example: The doctor suggested that he take a rest.
Watch out: Do not add -s or -ed, and put not before the base verb: that he take, not that he takes; that she not be late, not that she is not late.', '[{"label":"When to use","text":"After verbs and adjectives of advising, requesting or necessity (suggest, insist, recommend, it is essential / vital that…)."},{"label":"Look for","text":"one of these words + that. The next verb stays in its base form for every subject: he take, it be repaired, they not be late."},{"label":"Example","text":"The doctor suggested that he take a rest."},{"label":"Watch out","text":"Do not add -s or -ed, and put not before the base verb: that he take, not that he takes; that she not be late, not that she is not late."}]', 1901);
