INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-021-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-021-01'), 'micro_feedback', 'A05-T01', 'Time clauses (when, while, as soon as, until, once)', 'When to use: To say when something happens in relation to another action: before, after, at the same time or up to a point.
Key difference: while / as = at the same time; as soon as / once = immediately after; until = up to that point.
Example: We will leave as soon as the rain stops.
Watch out: Do not use will inside the time clause for the future: as soon as the rain stops, not as soon as the rain will stop.', '[{"label":"When to use","text":"To say when something happens in relation to another action: before, after, at the same time or up to a point."},{"label":"Key difference","text":"while / as = at the same time; as soon as / once = immediately after; until = up to that point."},{"label":"Example","text":"We will leave as soon as the rain stops."},{"label":"Watch out","text":"Do not use will inside the time clause for the future: as soon as the rain stops, not as soon as the rain will stop."}]', 2101);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-021-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-021-02'), 'micro_feedback', 'A05-T01', 'Time clauses (when, while, as soon as, until, once)', 'When to use: To say when something happens in relation to another action: before, after, at the same time or up to a point.
Key difference: while / as = at the same time; as soon as / once = immediately after; until = up to that point.
