INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-022-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-022-01'), 'micro_feedback', 'A05-T04', 'Giving reasons (because, since, as)', 'When to use: To explain why something happens. because gives the main reason; since and as often give a reason the listener already knows.
Look for: a cause and a result in the same sentence.
Example: Since it was late, we took a taxi home.
Watch out: Use only one linking word: Because it was late, we left, not Because it was late, so we left.', '[{"label":"When to use","text":"To explain why something happens. because gives the main reason; since and as often give a reason the listener already knows."},{"label":"Look for","text":"a cause and a result in the same sentence."},{"label":"Example","text":"Since it was late, we took a taxi home."},{"label":"Watch out","text":"Use only one linking word: Because it was late, we left, not Because it was late, so we left."}]', 2201);
