INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-023-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-023-06'), 'micro_feedback', 'A05-T12', 'Much as… (although I really…)', 'When to use: A formal way of saying although I really…, usually with feeling verbs such as like, enjoy, admire or want.
Look for: a strong feeling followed by a contrasting decision.
Example: Much as I enjoy working here, I have decided to leave.
Watch out: Follow Much as with a subject and a feeling verb: Much as I like him, not Much as the job or Much as I arrived late.', '[{"label":"When to use","text":"A formal way of saying although I really…, usually with feeling verbs such as like, enjoy, admire or want."},{"label":"Look for","text":"a strong feeling followed by a contrasting decision."},{"label":"Example","text":"Much as I enjoy working here, I have decided to leave."},{"label":"Watch out","text":"Follow Much as with a subject and a feeling verb: Much as I like him, not Much as the job or Much as I arrived late."}]', 2306);
