INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-023-13-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-023-13'), 'micro_feedback', 'A05-T13', 'even if (a possible situation)', 'When to use: To say the result will not change, whatever happens.
Key difference: even if = a possible or imagined situation; even though = a real fact.
Example: Even if it rains tomorrow, the match will go ahead.
Watch out: Do not use will after even if: Even if it rains, not Even if it will rain.', '[{"label":"When to use","text":"To say the result will not change, whatever happens."},{"label":"Key difference","text":"even if = a possible or imagined situation; even though = a real fact."},{"label":"Example","text":"Even if it rains tomorrow, the match will go ahead."},{"label":"Watch out","text":"Do not use will after even if: Even if it rains, not Even if it will rain."}]', 2313);
