INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-024-11-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-024-11'), 'micro_feedback', 'A05-T14', 'only if (a strict condition)', 'When to use: To say there is only one condition under which something happens.
Look for: a single requirement that must be met.
Example: You can enter the hall only if you have a ticket.
Watch out: Do not use will after if. If Only if starts the sentence, invert the main clause: Only if you have a ticket can you enter.', '[{"label":"When to use","text":"To say there is only one condition under which something happens."},{"label":"Look for","text":"a single requirement that must be met."},{"label":"Example","text":"You can enter the hall only if you have a ticket."},{"label":"Watch out","text":"Do not use will after if. If Only if starts the sentence, invert the main clause: Only if you have a ticket can you enter."}]', 2411);
