INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-024-26-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-024-26'), 'micro_feedback', 'A05-T15', 'unless (= if… not)', 'When to use: To say something will happen if a condition is not met.
Look for: except if meaning in the sentence.
Example: You cannot enter unless you have a ticket.
Watch out: unless already means if not, so do not add a negative: unless you have a ticket, not unless you don''t have a ticket.', '[{"label":"When to use","text":"To say something will happen if a condition is not met."},{"label":"Look for","text":"except if meaning in the sentence."},{"label":"Example","text":"You cannot enter unless you have a ticket."},{"label":"Watch out","text":"unless already means if not, so do not add a negative: unless you have a ticket, not unless you don''t have a ticket."}]', 2426);
