INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-025-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-025-01'), 'micro_feedback', 'A05-T20', 'Adding information (moreover, furthermore, in addition)', 'When to use: To add another point that supports what you have just said.
Look for: a second sentence that adds a similar or stronger point.
Example: The hotel was cheap. Moreover, it was close to the beach.
Watch out: Do not join two sentences with only a comma: It was cheap. Moreover, it was close to the beach, not It was cheap, moreover it was close to the beach.', '[{"label":"When to use","text":"To add another point that supports what you have just said."},{"label":"Look for","text":"a second sentence that adds a similar or stronger point."},{"label":"Example","text":"The hotel was cheap. Moreover, it was close to the beach."},{"label":"Watch out","text":"Do not join two sentences with only a comma: It was cheap. Moreover, it was close to the beach, not It was cheap, moreover it was close to the beach."}]', 2501);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-025-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-025-02'), 'micro_feedback', 'A05-T24', 'Short time phrases (while / after / before / upon + -ing)', 'When to use: To shorten a time clause when both parts have the same subject (While I was waiting → While waiting).
Look for: while, after, before, on or upon followed by an -ing form.
Example: Upon arriving at the hotel, we checked in immediately.
Watch out: The person after the comma must be the one doing the action: While waiting for the bus, I saw a friend, not While waiting for the bus, a friend saw me.', '[{"label":"When to use","text":"To shorten a time clause when both parts have the same subject (While I was waiting → While waiting)."},{"label":"Look for","text":"while, after, before, on or upon followed by an -ing form."},{"label":"Example","text":"Upon arriving at the hotel, we checked in immediately."},{"label":"Watch out","text":"The person after the comma must be the one doing the action: While waiting for the bus, I saw a friend, not While waiting for the bus, a friend saw me."}]', 2502);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-025-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-025-03'), 'micro_feedback', 'A05-T21', 'Contrast (however, nevertheless, in contrast, on the other hand)', 'When to use: To show a contrast or an unexpected result between two sentences.
Key difference: however / nevertheless = an unexpected result; in contrast / on the other hand = a comparison of two things.
Example: The test was difficult. Nevertheless, most students passed.
Watch out: however links sentences, not clauses: It was late. However, we stayed, not It was late however we stayed.', '[{"label":"When to use","text":"To show a contrast or an unexpected result between two sentences."},{"label":"Key difference","text":"however / nevertheless = an unexpected result; in contrast / on the other hand = a comparison of two things."},{"label":"Example","text":"The test was difficult. Nevertheless, most students passed."},{"label":"Watch out","text":"however links sentences, not clauses: It was late. However, we stayed, not It was late however we stayed."}]', 2503);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-025-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-025-04'), 'micro_feedback', 'A05-T22', 'Results (therefore, consequently, as a result, otherwise)', 'When to use: To show that one thing is the result of another.
Key difference: therefore / consequently / as a result = so; otherwise = if not.
Example: Hurry up; otherwise, we will miss the bus.
Watch out: Use otherwise for ‘if not’, not therefore: Leave now; otherwise you''ll be late.', '[{"label":"When to use","text":"To show that one thing is the result of another."},{"label":"Key difference","text":"therefore / consequently / as a result = so; otherwise = if not."},{"label":"Example","text":"Hurry up; otherwise, we will miss the bus."},{"label":"Watch out","text":"Use otherwise for ‘if not’, not therefore: Leave now; otherwise you''ll be late."}]', 2504);
