INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-05-025-11-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-05-025-11'), 'micro_feedback', 'A05-T25', 'Having + past participle (Having finished…)', 'When to use: To show that one action was completed before the next one.
Look for: two actions in sequence by the same person.
Example: Having finished her homework, she went out to play.
Watch out: Use Having done, not Had done or the base verb: Having reviewed the notes, he felt ready, not Had reviewed the notes, he felt ready.', '[{"label":"When to use","text":"To show that one action was completed before the next one."},{"label":"Look for","text":"two actions in sequence by the same person."},{"label":"Example","text":"Having finished her homework, she went out to play."},{"label":"Watch out","text":"Use Having done, not Had done or the base verb: Having reviewed the notes, he felt ready, not Had reviewed the notes, he felt ready."}]', 2511);
