INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-026-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-026-01'), 'micro_feedback', 'A06-T01', 'Zero conditional: facts and general truths', 'When to use: For things that are always true, such as scientific facts, rules and habits.
Look for: if / when + present, then present in the main clause.
Example: If you heat ice, it melts.
Watch out: For general facts, both parts usually stay in the present: If you heat ice, it melts is the standard form.', '[{"label":"When to use","text":"For things that are always true, such as scientific facts, rules and habits."},{"label":"Look for","text":"if / when + present, then present in the main clause."},{"label":"Example","text":"If you heat ice, it melts."},{"label":"Watch out","text":"For general facts, both parts usually stay in the present: If you heat ice, it melts is the standard form."}]', 2601);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-026-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-026-02'), 'micro_feedback', 'A06-T02', 'First conditional: real future possibilities', 'When to use: For a situation that may really happen in the future and its likely result.
Look for: if + present, then will / won''t + base verb.
Example: If it rains tomorrow, we will cancel the picnic.
Watch out: Do not put will in the if-part: If it rains tomorrow, not If it will rain tomorrow.', '[{"label":"When to use","text":"For a situation that may really happen in the future and its likely result."},{"label":"Look for","text":"if + present, then will / won''t + base verb."},{"label":"Example","text":"If it rains tomorrow, we will cancel the picnic."},{"label":"Watch out","text":"Do not put will in the if-part: If it rains tomorrow, not If it will rain tomorrow."}]', 2602);
