INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-026-09-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-026-09'), 'micro_feedback', 'A06-T03', 'if + instruction (If you…, call me.)', 'When to use: To give an instruction or advice that applies if something happens.
Look for: if + present (or present perfect), then a command starting with a base verb.
Example: If you finish early, wait outside.
Watch out: Keep the if-part in the present: If you finish early, wait outside, not If you will finish early, wait outside.', '[{"label":"When to use","text":"To give an instruction or advice that applies if something happens."},{"label":"Look for","text":"if + present (or present perfect), then a command starting with a base verb."},{"label":"Example","text":"If you finish early, wait outside."},{"label":"Watch out","text":"Keep the if-part in the present: If you finish early, wait outside, not If you will finish early, wait outside."}]', 2609);
