INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-028-26-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-028-26'), 'micro_feedback', 'A06-T10', 'Third conditional with might have', 'When to use: To talk about a past result that was possible but not certain.
Key difference: would have = certain result; might have = possible result.
Example: If we had left earlier, we might have found a parking space.
Watch out: Use might have + past participle, not might + base verb, for the past.', '[{"label":"When to use","text":"To talk about a past result that was possible but not certain."},{"label":"Key difference","text":"would have = certain result; might have = possible result."},{"label":"Example","text":"If we had left earlier, we might have found a parking space."},{"label":"Watch out","text":"Use might have + past participle, not might + base verb, for the past."}]', 2826);
