INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-029-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-029-01'), 'micro_feedback', 'A06-T11', 'Mixed conditional: past cause, present result', 'When to use: When something different in the past would change the situation now.
Look for: if + had + past participle, then would + base verb, often with now or today.
Example: If I had studied medicine, I would be a doctor now.
Watch out: Do not use would have when the result is about now: I would be tired now, not I would have been tired now.', '[{"label":"When to use","text":"When something different in the past would change the situation now."},{"label":"Look for","text":"if + had + past participle, then would + base verb, often with now or today."},{"label":"Example","text":"If I had studied medicine, I would be a doctor now."},{"label":"Watch out","text":"Do not use would have when the result is about now: I would be tired now, not I would have been tired now."}]', 2901);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-029-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-029-02'), 'micro_feedback', 'A06-T12', 'Mixed conditional: present fact, past result', 'When to use: When a permanent fact or quality would have changed something in the past.
Look for: if + past simple or were (a lasting fact), then would have + past participle.
Example: If I were taller, I would have joined the basketball team.
Watch out: Use the past simple for a permanent quality: If I were taller, not If I had been taller, when you mean ‘in general’.', '[{"label":"When to use","text":"When a permanent fact or quality would have changed something in the past."},{"label":"Look for","text":"if + past simple or were (a lasting fact), then would have + past participle."},{"label":"Example","text":"If I were taller, I would have joined the basketball team."},{"label":"Watch out","text":"Use the past simple for a permanent quality: If I were taller, not If I had been taller, when you mean ‘in general’."}]', 2902);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-029-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-029-03'), 'micro_feedback', 'A06-T11', 'Mixed conditional: past cause, present result', 'When to use: When something different in the past would change the situation now.
Look for: if + had + past participle, then would + base verb, often with now or today.
Example: If I had studied medicine, I would be a doctor now.
Watch out: Do not use would have when the result is about now: I would be tired now, not I would have been tired now.', '[{"label":"When to use","text":"When something different in the past would change the situation now."},{"label":"Look for","text":"if + had + past participle, then would + base verb, often with now or today."},{"label":"Example","text":"If I had studied medicine, I would be a doctor now."},{"label":"Watch out","text":"Do not use would have when the result is about now: I would be tired now, not I would have been tired now."}]', 2903);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-029-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-029-04'), 'micro_feedback', 'A06-T13', 'Mixed conditional: past cause, present ability', 'When to use: When a past action would give someone an ability or opportunity now.
Look for: if + had + past participle, then could + base verb.
Example: If I had saved money, I could buy a car now.
Watch out: Use could + base verb for a present ability: could buy now, not could have bought now.', '[{"label":"When to use","text":"When a past action would give someone an ability or opportunity now."},{"label":"Look for","text":"if + had + past participle, then could + base verb."},{"label":"Example","text":"If I had saved money, I could buy a car now."},{"label":"Watch out","text":"Use could + base verb for a present ability: could buy now, not could have bought now."}]', 2904);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-029-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-029-05'), 'micro_feedback', 'A06-T14', 'Mixed conditional: lasting skill, past result', 'When to use: When a permanent skill or quality would have changed a past event.
Look for: if + past simple (knew, spoke, were able to), then would have / could have + past participle.
Example: If I knew how to swim, I could have helped him.
Watch out: Use the past simple for a lasting skill: If I spoke French, not If I had spoken French.', '[{"label":"When to use","text":"When a permanent skill or quality would have changed a past event."},{"label":"Look for","text":"if + past simple (knew, spoke, were able to), then would have / could have + past participle."},{"label":"Example","text":"If I knew how to swim, I could have helped him."},{"label":"Watch out","text":"Use the past simple for a lasting skill: If I spoke French, not If I had spoken French."}]', 2905);
