INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-030-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-030-01'), 'micro_feedback', 'A06-T16', 'Wishes about the present (wish / if only + past)', 'When to use: To say you want the present situation to be different.
Look for: wish or if only + past simple or were.
Example: I wish I had more free time.
Watch out: Do not use the present: I wish I had, not I wish I have.', '[{"label":"When to use","text":"To say you want the present situation to be different."},{"label":"Look for","text":"wish or if only + past simple or were."},{"label":"Example","text":"I wish I had more free time."},{"label":"Watch out","text":"Do not use the present: I wish I had, not I wish I have."}]', 3001);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-030-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-030-02'), 'micro_feedback', 'A06-T17', 'Regrets about the past (wish / if only + had done)', 'When to use: To express regret about something that happened or did not happen.
Look for: wish or if only + had / hadn''t + past participle.
Example: If only I had checked the time.
Watch out: Do not use would have: I wish I had known, not I wish I would have known.', '[{"label":"When to use","text":"To express regret about something that happened or did not happen."},{"label":"Look for","text":"wish or if only + had / hadn''t + past participle."},{"label":"Example","text":"If only I had checked the time."},{"label":"Watch out","text":"Do not use would have: I wish I had known, not I wish I would have known."}]', 3002);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-030-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-030-03'), 'micro_feedback', 'A06-T22', 'Formal conditionals without if (Should you…, Were he to…, Had I known…)', 'When to use: In formal English, to replace if by putting should, were or had first.
Look for: a sentence starting with Should, Were or Had + subject.
Example: Had I known about the delay, I would have taken a taxi.
Watch out: Do not keep if: Had I known, not If had I known.', '[{"label":"When to use","text":"In formal English, to replace if by putting should, were or had first."},{"label":"Look for","text":"a sentence starting with Should, Were or Had + subject."},{"label":"Example","text":"Had I known about the delay, I would have taken a taxi."},{"label":"Watch out","text":"Do not keep if: Had I known, not If had I known."}]', 3003);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-030-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-030-04'), 'micro_feedback', 'A06-T21', 'would rather + someone else + past', 'When to use: To say what you would prefer another person to do.
Look for: would rather + a different person + past simple.
Example: I would rather you stayed at home tonight.
Watch out: The past simple is the expected answer: I''d rather you came tomorrow (In informal speech or American English, you may also hear come, but choose the past form in a test).', '[{"label":"When to use","text":"To say what you would prefer another person to do."},{"label":"Look for","text":"would rather + a different person + past simple."},{"label":"Example","text":"I would rather you stayed at home tonight."},{"label":"Watch out","text":"The past simple is the expected answer: I''d rather you came tomorrow (In informal speech or American English, you may also hear come, but choose the past form in a test)."}]', 3004);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-06-030-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-06-030-05'), 'micro_feedback', 'A06-T20', 'It''s high time + past simple', 'When to use: A stronger way of saying something is overdue, often as criticism.
Look for: It''s high time + subject + past simple.
Example: It''s high time you learned to cook.
Watch out: After a subject, use the past simple: It''s high time we started, not It''s high time we start. (It''s high time to start is fine without a subject.)', '[{"label":"When to use","text":"A stronger way of saying something is overdue, often as criticism."},{"label":"Look for","text":"It''s high time + subject + past simple."},{"label":"Example","text":"It''s high time you learned to cook."},{"label":"Watch out","text":"After a subject, use the past simple: It''s high time we started, not It''s high time we start. (It''s high time to start is fine without a subject.)"}]', 3005);
