INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-01'), 'micro_feedback', 'A07-T01', 'Reported speech: moving present tenses back', 'When to use: When you report someone''s words with a past verb such as said or told.
Look for: a past reporting verb. Move present forms one step back: is → was, is doing → was doing, has done → had done.
Example: ‘I am tired.’ → He said he was tired.
Watch out: Do not keep the present after said when the situation has changed: He said he was tired, not He said he is tired.', '[{"label":"When to use","text":"When you report someone''s words with a past verb such as said or told."},{"label":"Look for","text":"a past reporting verb. Move present forms one step back: is → was, is doing → was doing, has done → had done."},{"label":"Example","text":"‘I am tired.’ → He said he was tired."},{"label":"Watch out","text":"Do not keep the present after said when the situation has changed: He said he was tired, not He said he is tired."}]', 3101);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-02'), 'micro_feedback', 'A07-T01', 'Reported speech: moving present tenses back', 'When to use: When you report someone''s words with a past verb such as said or told.
Look for: a past reporting verb. Move present forms one step back: is → was, is doing → was doing, has done → had done.
Example: ‘I am tired.’ → He said he was tired.
Watch out: Do not keep the present after said when the situation has changed: He said he was tired, not He said he is tired.', '[{"label":"When to use","text":"When you report someone''s words with a past verb such as said or told."},{"label":"Look for","text":"a past reporting verb. Move present forms one step back: is → was, is doing → was doing, has done → had done."},{"label":"Example","text":"‘I am tired.’ → He said he was tired."},{"label":"Watch out","text":"Do not keep the present after said when the situation has changed: He said he was tired, not He said he is tired."}]', 3102);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-03'), 'micro_feedback', 'A07-T07', 'No tense change for facts that are always true', 'When to use: When the reported words are a scientific fact, a general truth or something still true.
Look for: facts about nature, science or permanent habits.
Example: The teacher said that water boils at 100°C.
Watch out: You may keep the present for facts that are always true: He said that the earth revolves around the sun.', '[{"label":"When to use","text":"When the reported words are a scientific fact, a general truth or something still true."},{"label":"Look for","text":"facts about nature, science or permanent habits."},{"label":"Example","text":"The teacher said that water boils at 100°C."},{"label":"Watch out","text":"You may keep the present for facts that are always true: He said that the earth revolves around the sun."}]', 3103);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-04'), 'micro_feedback', 'A07-T01', 'Reported speech: moving present tenses back', 'When to use: When you report someone''s words with a past verb such as said or told.
Look for: a past reporting verb. Move present forms one step back: is → was, is doing → was doing, has done → had done.
Example: ‘I am tired.’ → He said he was tired.
Watch out: Do not keep the present after said when the situation has changed: He said he was tired, not He said he is tired.', '[{"label":"When to use","text":"When you report someone''s words with a past verb such as said or told."},{"label":"Look for","text":"a past reporting verb. Move present forms one step back: is → was, is doing → was doing, has done → had done."},{"label":"Example","text":"‘I am tired.’ → He said he was tired."},{"label":"Watch out","text":"Do not keep the present after said when the situation has changed: He said he was tired, not He said he is tired."}]', 3104);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-05'), 'micro_feedback', 'A07-T02', 'Reported speech: past → past perfect', 'When to use: When the original words were already in the past and you report them later.
Look for: a past event inside the reported words. did → had done; was doing → had been doing.
Example: ‘I lost my keys.’ → She said she had lost her keys.
Watch out: Use had + past participle to show the event happened earlier: had lost, not has lost.', '[{"label":"When to use","text":"When the original words were already in the past and you report them later."},{"label":"Look for","text":"a past event inside the reported words. did → had done; was doing → had been doing."},{"label":"Example","text":"‘I lost my keys.’ → She said she had lost her keys."},{"label":"Watch out","text":"Use had + past participle to show the event happened earlier: had lost, not has lost."}]', 3105);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-06'), 'micro_feedback', 'A07-T03', 'Reported speech: will → would', 'When to use: When reporting future plans, promises or predictions with a past reporting verb.
Look for: will or will have in the original words. Change to would / would have.
Example: ‘I will send the email.’ → She said she would send the email.
Watch out: Do not keep will after said: She said she would call, not She said she will call.', '[{"label":"When to use","text":"When reporting future plans, promises or predictions with a past reporting verb."},{"label":"Look for","text":"will or will have in the original words. Change to would / would have."},{"label":"Example","text":"‘I will send the email.’ → She said she would send the email."},{"label":"Watch out","text":"Do not keep will after said: She said she would call, not She said she will call."}]', 3106);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-07'), 'micro_feedback', 'A07-T07', 'No tense change for facts that are always true', 'When to use: When the reported words are a scientific fact, a general truth or something still true.
Look for: facts about nature, science or permanent habits.
