INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-11-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-11'), 'micro_feedback', 'A07-T05', 'No tense change after a present reporting verb', 'When to use: When the reporting verb is in the present (says, tells, explains), often for news or messages just received.
Look for: says / tells + reported words. Keep the original tense.
Example: She says she wants to leave early.
Watch out: Do not move the tense back after a present verb: She says she wants, not She says she wanted.', '[{"label":"When to use","text":"When the reporting verb is in the present (says, tells, explains), often for news or messages just received."},{"label":"Look for","text":"says / tells + reported words. Keep the original tense."},{"label":"Example","text":"She says she wants to leave early."},{"label":"Watch out","text":"Do not move the tense back after a present verb: She says she wants, not She says she wanted."}]', 3111);
