INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-29-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-29'), 'micro_feedback', 'A07-T02', 'Reported speech: past → past perfect', 'When to use: When the original words were already in the past and you report them later.
Look for: a past event inside the reported words. did → had done; was doing → had been doing.
Example: ‘I lost my keys.’ → She said she had lost her keys.
Watch out: Use had + past participle to show the event happened earlier: had lost, not has lost.', '[{"label":"When to use","text":"When the original words were already in the past and you report them later."},{"label":"Look for","text":"a past event inside the reported words. did → had done; was doing → had been doing."},{"label":"Example","text":"‘I lost my keys.’ → She said she had lost her keys."},{"label":"Watch out","text":"Use had + past participle to show the event happened earlier: had lost, not has lost."}]', 3129);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-031-30-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-031-30'), 'micro_feedback', 'A07-T05', 'No tense change after a present reporting verb', 'When to use: When the reporting verb is in the present (says, tells, explains), often for news or messages just received.
Look for: says / tells + reported words. Keep the original tense.
Example: She says she wants to leave early.
Watch out: Do not move the tense back after a present verb: She says she wants, not She says she wanted.', '[{"label":"When to use","text":"When the reporting verb is in the present (says, tells, explains), often for news or messages just received."},{"label":"Look for","text":"says / tells + reported words. Keep the original tense."},{"label":"Example","text":"She says she wants to leave early."},{"label":"Watch out","text":"Do not move the tense back after a present verb: She says she wants, not She says she wanted."}]', 3130);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-032-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-032-01'), 'micro_feedback', 'A07-T09', 'Reported wh- questions (word order)', 'When to use: When reporting a question with what, where, when, why, how or who.
Look for: question word + subject + verb (tense moved back).
Example: ‘Where are you going?’ → She asked where I was going.
Watch out: Do not use question order: where I was going, not where was I going or where did I go.', '[{"label":"When to use","text":"When reporting a question with what, where, when, why, how or who."},{"label":"Look for","text":"question word + subject + verb (tense moved back)."},{"label":"Example","text":"‘Where are you going?’ → She asked where I was going."},{"label":"Watch out","text":"Do not use question order: where I was going, not where was I going or where did I go."}]', 3201);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-032-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-032-02'), 'micro_feedback', 'A07-T08', 'Reported yes/no questions (asked if / whether)', 'When to use: When reporting a question that has a yes/no answer.
