INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-033-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-033-01'), 'micro_feedback', 'A07-T10', 'Reporting requests and orders (ask / tell + person + to)', 'When to use: When reporting a request, instruction or command.
Look for: asked / told / ordered / instructed + person + (not) to + base verb.
Example: ‘Please don''t make noise.’ → She asked us not to make noise.
Watch out: Put not before to: asked me not to leave, not asked me to not leave. Drop please and could you.', '[{"label":"When to use","text":"When reporting a request, instruction or command."},{"label":"Look for","text":"asked / told / ordered / instructed + person + (not) to + base verb."},{"label":"Example","text":"‘Please don''t make noise.’ → She asked us not to make noise."},{"label":"Watch out","text":"Put not before to: asked me not to leave, not asked me to not leave. Drop please and could you."}]', 3301);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-033-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-033-02'), 'micro_feedback', 'A07-T11', 'Reporting warnings (warn + person + not to)', 'When to use: When reporting a warning.
Look for: warned + person + not to / never to + base verb.
Example: ‘Don''t touch the wire!’ → He warned us not to touch the wire.
Watch out: Include the person after warn: He warned us not to enter, not He warned to not enter.', '[{"label":"When to use","text":"When reporting a warning."},{"label":"Look for","text":"warned + person + not to / never to + base verb."},{"label":"Example","text":"‘Don''t touch the wire!’ → He warned us not to touch the wire."},{"label":"Watch out","text":"Include the person after warn: He warned us not to enter, not He warned to not enter."}]', 3302);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-033-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-033-03'), 'micro_feedback', 'A07-T12', 'Reporting offers (offer to)', 'When to use: When reporting that someone offered to do something.
Look for: offered + to + base verb.
Example: ‘Shall I help you?’ → She offered to help me.
Watch out: Do not put a person between offer and to: He offered to drive us, not He offered us to drive.', '[{"label":"When to use","text":"When reporting that someone offered to do something."},{"label":"Look for","text":"offered + to + base verb."},{"label":"Example","text":"‘Shall I help you?’ → She offered to help me."},{"label":"Watch out","text":"Do not put a person between offer and to: He offered to drive us, not He offered us to drive."}]', 3303);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-033-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-033-04'), 'micro_feedback', 'A07-T13', 'Reporting advice and suggestions (advise vs suggest)', 'When to use: When reporting advice or a suggestion.
Key difference: advise + person + to do; suggest / propose / recommend + -ing or that + subject + verb.
Examples: She advised me to see a doctor. He suggested hiring a new assistant.
Watch out: suggest is not followed by person + to: He suggested that I study, not He suggested me to study.', '[{"label":"When to use","text":"When reporting advice or a suggestion."},{"label":"Key difference","text":"advise + person + to do; suggest / propose / recommend + -ing or that + subject + verb."},{"label":"Examples","text":"She advised me to see a doctor. He suggested hiring a new assistant."},{"label":"Watch out","text":"suggest is not followed by person + to: He suggested that I study, not He suggested me to study."}]', 3304);
