INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-034-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-034-01'), 'micro_feedback', 'A07-T16', 'Reporting verbs + preposition + -ing (apologise for, insist on)', 'When to use: When the reporting verb needs a preposition before the action.
Look for: apologise for, thank someone for, accuse someone of, blame someone for, insist on, congratulate someone on, object to, confess to + -ing.
Example: She apologised for missing the meeting.
Watch out: Do not use to + base verb: insisted on paying, not insisted to pay. Use the correct preposition: accused him of, not accused him for.', '[{"label":"When to use","text":"When the reporting verb needs a preposition before the action."},{"label":"Look for","text":"apologise for, thank someone for, accuse someone of, blame someone for, insist on, congratulate someone on, object to, confess to + -ing."},{"label":"Example","text":"She apologised for missing the meeting."},{"label":"Watch out","text":"Do not use to + base verb: insisted on paying, not insisted to pay. Use the correct preposition: accused him of, not accused him for."}]', 3401);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-034-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-034-02'), 'micro_feedback', 'A07-T16', 'Reporting verbs + preposition + -ing (apologise for, insist on)', 'When to use: When the reporting verb needs a preposition before the action.
