INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-01'), 'micro_feedback', 'A07-T20', 'Reported speech: here → there', 'When to use: When you report words in a different place from where they were spoken.
Look for: here in the original words.
Example: ‘I like working here.’ → She said she liked working there.
Watch out: Change here to there when the report is made somewhere else.', '[{"label":"When to use","text":"When you report words in a different place from where they were spoken."},{"label":"Look for","text":"here in the original words."},{"label":"Example","text":"‘I like working here.’ → She said she liked working there."},{"label":"Watch out","text":"Change here to there when the report is made somewhere else."}]', 3501);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-02'), 'micro_feedback', 'A07-T23', 'Reporting a first conditional', 'When to use: When reporting an if-sentence about a real future possibility.
Look for: both parts move back: if + present → if + past; will → would.
Example: ‘If you pass, you will get the job.’ → He said that if I passed, I would get the job.
Watch out: Change both verbs: if I passed, I would, not if I pass, I would.', '[{"label":"When to use","text":"When reporting an if-sentence about a real future possibility."},{"label":"Look for","text":"both parts move back: if + present → if + past; will → would."},{"label":"Example","text":"‘If you pass, you will get the job.’ → He said that if I passed, I would get the job."},{"label":"Watch out","text":"Change both verbs: if I passed, I would, not if I pass, I would."}]', 3502);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-03'), 'micro_feedback', 'A07-T26', 'Modals that do not change (should, could, might, ought to)', 'When to use: When the original words contain a modal that is already in its ‘past’ form.
Look for: should, could, might, would, ought to, and must for a logical guess.
Example: ‘You should rest.’ → The doctor said I should rest.
Watch out: Keep these modals unchanged: He said we should start, not He said we should have started.', '[{"label":"When to use","text":"When the original words contain a modal that is already in its ‘past’ form."},{"label":"Look for","text":"should, could, might, would, ought to, and must for a logical guess."},{"label":"Example","text":"‘You should rest.’ → The doctor said I should rest."},{"label":"Watch out","text":"Keep these modals unchanged: He said we should start, not He said we should have started."}]', 3503);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-04'), 'micro_feedback', 'A07-T21', 'Reported speech: changing time words', 'When to use: When you report words at a later time.
Look for: tomorrow → the next day / the following day; yesterday → the day before; last week → the previous week; ago → before; now → then.
Example: ‘I''ll call you tomorrow.’ → He said he would call me the next day.
Watch out: Do not keep tomorrow or yesterday when that day has passed.', '[{"label":"When to use","text":"When you report words at a later time."},{"label":"Look for","text":"tomorrow → the next day / the following day; yesterday → the day before; last week → the previous week; ago → before; now → then."},{"label":"Example","text":"‘I''ll call you tomorrow.’ → He said he would call me the next day."},{"label":"Watch out","text":"Do not keep tomorrow or yesterday when that day has passed."}]', 3504);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-05'), 'micro_feedback', 'A07-T24', 'Reporting a second conditional (no change)', 'When to use: When reporting an imagined if-sentence.
Look for: if + past simple / were, then would + base verb. Keep it as it is.
Example: He said that if he had a car, he would drive to work.
Watch out: Do not move it back further: if he had a car, not if he had had a car.', '[{"label":"When to use","text":"When reporting an imagined if-sentence."},{"label":"Look for","text":"if + past simple / were, then would + base verb. Keep it as it is."},{"label":"Example","text":"He said that if he had a car, he would drive to work."},{"label":"Watch out","text":"Do not move it back further: if he had a car, not if he had had a car."}]', 3505);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-06'), 'micro_feedback', 'A07-T28', 'used to does not change', 'When to use: When reporting a past habit with used to.
Look for: used to + base verb in the original words.
Example: ‘I used to play the piano.’ → He said he used to play the piano.
Watch out: Keep used to: He said he used to work here, not He said he had used to work here.', '[{"label":"When to use","text":"When reporting a past habit with used to."},{"label":"Look for","text":"used to + base verb in the original words."},{"label":"Example","text":"‘I used to play the piano.’ → He said he used to play the piano."},{"label":"Watch out","text":"Keep used to: He said he used to work here, not He said he had used to work here."}]', 3506);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-07'), 'micro_feedback', 'A07-T22', 'Reported speech: this / these → that / those', 'When to use: When the things being talked about are no longer near or present.
Look for: this or these in the original words.
Example: ‘I need these files.’ → She said she needed those files.
Watch out: Change this to that and these to those when reporting later.', '[{"label":"When to use","text":"When the things being talked about are no longer near or present."},{"label":"Look for","text":"this or these in the original words."},{"label":"Example","text":"‘I need these files.’ → She said she needed those files."},{"label":"Watch out","text":"Change this to that and these to those when reporting later."}]', 3507);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-08-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-08'), 'micro_feedback', 'A07-T25', 'Reporting a third conditional (no change)', 'When to use: When reporting an if-sentence about the imagined past.
Look for: if + had done, then would have done. Keep it as it is.
Example: She said that if I had asked, she would have helped.
Watch out: Keep would have + past participle in the result part; do not change it.', '[{"label":"When to use","text":"When reporting an if-sentence about the imagined past."},{"label":"Look for","text":"if + had done, then would have done. Keep it as it is."},{"label":"Example","text":"She said that if I had asked, she would have helped."},{"label":"Watch out","text":"Keep would have + past participle in the result part; do not change it."}]', 3508);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-09-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-09'), 'micro_feedback', 'A07-T26', 'Modals that do not change (should, could, might, ought to)', 'When to use: When the original words contain a modal that is already in its ‘past’ form.
Look for: should, could, might, would, ought to, and must for a logical guess.
Example: ‘You should rest.’ → The doctor said I should rest.
