INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-07-035-27-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-07-035-27'), 'micro_feedback', 'A07-T27', 'must for rules that are still true', 'When to use: When reporting a rule or requirement that is still in place.
Look for: must for laws, regulations and permanent rules.
Example: She said applicants must be over 18.
Watch out: You can keep must when the rule still applies; had to is used for one-time obligations in the past.', '[{"label":"When to use","text":"When reporting a rule or requirement that is still in place."},{"label":"Look for","text":"must for laws, regulations and permanent rules."},{"label":"Example","text":"She said applicants must be over 18."},{"label":"Watch out","text":"You can keep must when the rule still applies; had to is used for one-time obligations in the past."}]', 3527);
