INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-01'), 'micro_feedback', 'A08-T01', 'remember / forget + -ing or to', 'When to use: When the meaning depends on whether the action is in the past or still to be done.
Key difference: remember / forget + -ing = a memory of something you did; + to = a task you need to do.
Examples: I''ll never forget meeting the President. Don''t forget to lock the door.
Watch out: I remember locking the door (I did it); Remember to lock the door (do it).', '[{"label":"When to use","text":"When the meaning depends on whether the action is in the past or still to be done."},{"label":"Key difference","text":"remember / forget + -ing = a memory of something you did; + to = a task you need to do."},{"label":"Examples","text":"I''ll never forget meeting the President. Don''t forget to lock the door."},{"label":"Watch out","text":"I remember locking the door (I did it); Remember to lock the door (do it)."}]', 3601);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-02'), 'micro_feedback', 'A08-T03', 'stop + -ing or to', 'When to use: When the meaning depends on whether an activity ends or is paused for a reason.
Key difference: stop + -ing = end an activity; stop + to = pause in order to do something else.
Examples: Please stop talking. We stopped to buy some water.
Watch out: stop to talk means ‘stop in order to talk’, not ‘be quiet’.', '[{"label":"When to use","text":"When the meaning depends on whether an activity ends or is paused for a reason."},{"label":"Key difference","text":"stop + -ing = end an activity; stop + to = pause in order to do something else."},{"label":"Examples","text":"Please stop talking. We stopped to buy some water."},{"label":"Watch out","text":"stop to talk means ‘stop in order to talk’, not ‘be quiet’."}]', 3602);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-03'), 'micro_feedback', 'A08-T04', 'try + -ing or to', 'When to use: When the meaning depends on whether you experiment or make an effort.
Key difference: try + -ing = test a method to see if it works; try + to = make an effort to do something difficult.
Examples: If you can''t sleep, try reading a book. He tried to lift the box, but it was too heavy.
Watch out: For advice about a possible solution, use try + -ing.', '[{"label":"When to use","text":"When the meaning depends on whether you experiment or make an effort."},{"label":"Key difference","text":"try + -ing = test a method to see if it works; try + to = make an effort to do something difficult."},{"label":"Examples","text":"If you can''t sleep, try reading a book. He tried to lift the box, but it was too heavy."},{"label":"Watch out","text":"For advice about a possible solution, use try + -ing."}]', 3603);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-04'), 'micro_feedback', 'A08-T05', 'mean + -ing or to', 'When to use: When the meaning depends on whether you talk about a result or an intention.
Key difference: mean + -ing = involve or result in; mean + to = intend.
Examples: Taking the job means moving to London. I didn''t mean to upset you.
Watch out: For what a decision involves, use -ing: means working late, not means to work late.', '[{"label":"When to use","text":"When the meaning depends on whether you talk about a result or an intention."},{"label":"Key difference","text":"mean + -ing = involve or result in; mean + to = intend."},{"label":"Examples","text":"Taking the job means moving to London. I didn''t mean to upset you."},{"label":"Watch out","text":"For what a decision involves, use -ing: means working late, not means to work late."}]', 3604);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-05'), 'micro_feedback', 'A08-T02', 'regret + -ing or to', 'When to use: To talk about feeling sorry about the past, or to give bad news politely.
Key difference: regret + -ing = sorry about something you did; regret to inform / tell / say = sorry about news you are giving now.
Examples: I regret shouting at him. We regret to inform you that the flight is cancelled.
Watch out: Use regret to inform for formal announcements, not regret informing.', '[{"label":"When to use","text":"To talk about feeling sorry about the past, or to give bad news politely."},{"label":"Key difference","text":"regret + -ing = sorry about something you did; regret to inform / tell / say = sorry about news you are giving now."},{"label":"Examples","text":"I regret shouting at him. We regret to inform you that the flight is cancelled."},{"label":"Watch out","text":"Use regret to inform for formal announcements, not regret informing."}]', 3605);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-06'), 'micro_feedback', 'A08-T06', 'go on + -ing or to', 'When to use: When the meaning depends on whether an action continues or a new action follows.
Key difference: go on + -ing = continue the same activity; go on + to = move to the next activity.
Examples: She went on talking for an hour. After welcoming the guests, he went on to present the awards.
Watch out: Use go on to for the next step in a sequence.', '[{"label":"When to use","text":"When the meaning depends on whether an action continues or a new action follows."},{"label":"Key difference","text":"go on + -ing = continue the same activity; go on + to = move to the next activity."},{"label":"Examples","text":"She went on talking for an hour. After welcoming the guests, he went on to present the awards."},{"label":"Watch out","text":"Use go on to for the next step in a sequence."}]', 3606);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-07'), 'micro_feedback', 'A08-T02', 'regret + -ing or to', 'When to use: To talk about feeling sorry about the past, or to give bad news politely.
Key difference: regret + -ing = sorry about something you did; regret to inform / tell / say = sorry about news you are giving now.
Examples: I regret shouting at him. We regret to inform you that the flight is cancelled.
Watch out: Use regret to inform for formal announcements, not regret informing.', '[{"label":"When to use","text":"To talk about feeling sorry about the past, or to give bad news politely."},{"label":"Key difference","text":"regret + -ing = sorry about something you did; regret to inform / tell / say = sorry about news you are giving now."},{"label":"Examples","text":"I regret shouting at him. We regret to inform you that the flight is cancelled."},{"label":"Watch out","text":"Use regret to inform for formal announcements, not regret informing."}]', 3607);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-08-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-08'), 'micro_feedback', 'A08-T03', 'stop + -ing or to', 'When to use: When the meaning depends on whether an activity ends or is paused for a reason.
Key difference: stop + -ing = end an activity; stop + to = pause in order to do something else.
