INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-09-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-09'), 'micro_feedback', 'A08-T01', 'remember / forget + -ing or to', 'When to use: When the meaning depends on whether the action is in the past or still to be done.
Key difference: remember / forget + -ing = a memory of something you did; + to = a task you need to do.
Examples: I''ll never forget meeting the President. Don''t forget to lock the door.
Watch out: I remember locking the door (I did it); Remember to lock the door (do it).', '[{"label":"When to use","text":"When the meaning depends on whether the action is in the past or still to be done."},{"label":"Key difference","text":"remember / forget + -ing = a memory of something you did; + to = a task you need to do."},{"label":"Examples","text":"I''ll never forget meeting the President. Don''t forget to lock the door."},{"label":"Watch out","text":"I remember locking the door (I did it); Remember to lock the door (do it)."}]', 3609);
