INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-11-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-11'), 'micro_feedback', 'A08-T04', 'try + -ing or to', 'When to use: When the meaning depends on whether you experiment or make an effort.
Key difference: try + -ing = test a method to see if it works; try + to = make an effort to do something difficult.
Examples: If you can''t sleep, try reading a book. He tried to lift the box, but it was too heavy.
Watch out: For advice about a possible solution, use try + -ing.', '[{"label":"When to use","text":"When the meaning depends on whether you experiment or make an effort."},{"label":"Key difference","text":"try + -ing = test a method to see if it works; try + to = make an effort to do something difficult."},{"label":"Examples","text":"If you can''t sleep, try reading a book. He tried to lift the box, but it was too heavy."},{"label":"Watch out","text":"For advice about a possible solution, use try + -ing."}]', 3611);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-12-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-12'), 'micro_feedback', 'A08-T05', 'mean + -ing or to', 'When to use: When the meaning depends on whether you talk about a result or an intention.
Key difference: mean + -ing = involve or result in; mean + to = intend.
Examples: Taking the job means moving to London. I didn''t mean to upset you.
Watch out: For what a decision involves, use -ing: means working late, not means to work late.', '[{"label":"When to use","text":"When the meaning depends on whether you talk about a result or an intention."},{"label":"Key difference","text":"mean + -ing = involve or result in; mean + to = intend."},{"label":"Examples","text":"Taking the job means moving to London. I didn''t mean to upset you."},{"label":"Watch out","text":"For what a decision involves, use -ing: means working late, not means to work late."}]', 3612);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-13-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-13'), 'micro_feedback', 'A08-T06', 'go on + -ing or to', 'When to use: When the meaning depends on whether an action continues or a new action follows.
Key difference: go on + -ing = continue the same activity; go on + to = move to the next activity.
Examples: She went on talking for an hour. After welcoming the guests, he went on to present the awards.
Watch out: Use go on to for the next step in a sequence.', '[{"label":"When to use","text":"When the meaning depends on whether an action continues or a new action follows."},{"label":"Key difference","text":"go on + -ing = continue the same activity; go on + to = move to the next activity."},{"label":"Examples","text":"She went on talking for an hour. After welcoming the guests, he went on to present the awards."},{"label":"Watch out","text":"Use go on to for the next step in a sequence."}]', 3613);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-036-14-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-036-14'), 'micro_feedback', 'A08-T07', 'dread + -ing or to', 'When to use: To talk about something you fear doing.
Key difference: dread + -ing = fear doing something; dread to think / imagine = a fixed phrase for something too awful to think about.
Examples: He dreads going to the dentist. I dread to think what might happen.
Watch out: Use to only with think or imagine: dreads going, not dreads to go.', '[{"label":"When to use","text":"To talk about something you fear doing."},{"label":"Key difference","text":"dread + -ing = fear doing something; dread to think / imagine = a fixed phrase for something too awful to think about."},{"label":"Examples","text":"He dreads going to the dentist. I dread to think what might happen."},{"label":"Watch out","text":"Use to only with think or imagine: dreads going, not dreads to go."}]', 3614);
