INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-01'), 'micro_feedback', 'A08-T17', 'decide + to', 'When to use: To talk about making a choice.
Look for: decide before the gap.
Example: They decided to cancel the meeting.
Watch out: Not decided cancelling.', '[{"label":"When to use","text":"To talk about making a choice."},{"label":"Look for","text":"decide before the gap."},{"label":"Example","text":"They decided to cancel the meeting."},{"label":"Watch out","text":"Not decided cancelling."}]', 3701);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-02'), 'micro_feedback', 'A08-T08', 'Verbs followed by -ing (avoid, consider)', 'When to use: After verbs such as avoid, consider, admit, delay, risk and suggest.
Look for: one of these verbs before the gap.
Example: She avoided answering the question.
Watch out: Do not use to after these verbs: considered moving, not considered to move.', '[{"label":"When to use","text":"After verbs such as avoid, consider, admit, delay, risk and suggest."},{"label":"Look for","text":"one of these verbs before the gap."},{"label":"Example","text":"She avoided answering the question."},{"label":"Watch out","text":"Do not use to after these verbs: considered moving, not considered to move."}]', 3702);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-03'), 'micro_feedback', 'A08-T10', 'make / let / see / hear + person + base verb', 'When to use: To say someone causes, allows, sees or hears another person doing something.
Look for: make / let / see / hear + person + base verb (no to).
Example: My boss lets me leave early on Fridays.
Watch out: No to after the person: She made him sign, not She made him to sign.', '[{"label":"When to use","text":"To say someone causes, allows, sees or hears another person doing something."},{"label":"Look for","text":"make / let / see / hear + person + base verb (no to)."},{"label":"Example","text":"My boss lets me leave early on Fridays."},{"label":"Watch out","text":"No to after the person: She made him sign, not She made him to sign."}]', 3703);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-04'), 'micro_feedback', 'A08-T12', 'delay / postpone + -ing', 'When to use: To say an action is put off until later.
Look for: delay or postpone before the gap.
Example: They postponed opening the museum.
Watch out: Not postponed to open or delayed to open.', '[{"label":"When to use","text":"To say an action is put off until later."},{"label":"Look for","text":"delay or postpone before the gap."},{"label":"Example","text":"They postponed opening the museum."},{"label":"Watch out","text":"Not postponed to open or delayed to open."}]', 3704);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-05'), 'micro_feedback', 'A08-T18', 'manage + to', 'When to use: To say someone succeeded in doing something difficult.
Look for: manage before the gap.
Example: She managed to find a solution.
Watch out: Not managed finding or managed in finding.', '[{"label":"When to use","text":"To say someone succeeded in doing something difficult."},{"label":"Look for","text":"manage before the gap."},{"label":"Example","text":"She managed to find a solution."},{"label":"Watch out","text":"Not managed finding or managed in finding."}]', 3705);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-06'), 'micro_feedback', 'A08-T19', 'deny + -ing', 'When to use: To report that someone said they did not do something.
Look for: deny before the gap.
Example: The suspect denied taking the cash.
Watch out: Not denied to take.', '[{"label":"When to use","text":"To report that someone said they did not do something."},{"label":"Look for","text":"deny before the gap."},{"label":"Example","text":"The suspect denied taking the cash."},{"label":"Watch out","text":"Not denied to take."}]', 3706);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-07'), 'micro_feedback', 'A08-T09', 'Verbs followed by to (agree, afford, promise, refuse)', 'When to use: After verbs about decisions, plans and promises (agree, afford, decide, promise, refuse).
Look for: one of these verbs before the gap.
Example: They refused to negotiate.
Watch out: Do not use -ing after these verbs: agreed to help, not agreed helping.', '[{"label":"When to use","text":"After verbs about decisions, plans and promises (agree, afford, decide, promise, refuse)."},{"label":"Look for","text":"one of these verbs before the gap."},{"label":"Example","text":"They refused to negotiate."},{"label":"Watch out","text":"Do not use -ing after these verbs: agreed to help, not agreed helping."}]', 3707);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-08-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-08'), 'micro_feedback', 'A08-T20', 'suggest + -ing or that-clause', 'When to use: To report an idea or proposal.
Look for: suggest + -ing, or suggest that + subject + verb.
Examples: He suggested taking a break. He suggested that we take a break.
Watch out: Not suggested to take or suggested us to take.', '[{"label":"When to use","text":"To report an idea or proposal."},{"label":"Look for","text":"suggest + -ing, or suggest that + subject + verb."},{"label":"Examples","text":"He suggested taking a break. He suggested that we take a break."},{"label":"Watch out","text":"Not suggested to take or suggested us to take."}]', 3708);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-09-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-09'), 'micro_feedback', 'A08-T10', 'make / let / see / hear + person + base verb', 'When to use: To say someone causes, allows, sees or hears another person doing something.
Look for: make / let / see / hear + person + base verb (no to).
Example: My boss lets me leave early on Fridays.
Watch out: No to after the person: She made him sign, not She made him to sign.', '[{"label":"When to use","text":"To say someone causes, allows, sees or hears another person doing something."},{"label":"Look for","text":"make / let / see / hear + person + base verb (no to)."},{"label":"Example","text":"My boss lets me leave early on Fridays."},{"label":"Watch out","text":"No to after the person: She made him sign, not She made him to sign."}]', 3709);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-10-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-10'), 'micro_feedback', 'A08-T08', 'Verbs followed by -ing (avoid, consider)', 'When to use: After verbs such as avoid, consider, admit, delay, risk and suggest.
