INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-12-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-12'), 'micro_feedback', 'A08-T21', 'risk + -ing', 'When to use: To talk about doing something that might cause a problem.
