INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-15-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-15'), 'micro_feedback', 'A08-T16', 'notice + person + base verb / -ing', 'When to use: To say you saw someone do or doing something.
Key difference: base verb = the whole action; -ing = part of an action in progress.
Example: I noticed her enter the room.
Watch out: No to: noticed her enter, not noticed her to enter.', '[{"label":"When to use","text":"To say you saw someone do or doing something."},{"label":"Key difference","text":"base verb = the whole action; -ing = part of an action in progress."},{"label":"Example","text":"I noticed her enter the room."},{"label":"Watch out","text":"No to: noticed her enter, not noticed her to enter."}]', 3715);
