INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-037-19-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-037-19'), 'micro_feedback', 'A08-T15', 'hope / plan / arrange + to', 'When to use: For plans and hopes about the future.
Look for: hope, plan or arrange before the gap.
Example: We plan to travel to Japan next year.
Watch out: Not plan travelling or plan of travelling.', '[{"label":"When to use","text":"For plans and hopes about the future."},{"label":"Look for","text":"hope, plan or arrange before the gap."},{"label":"Example","text":"We plan to travel to Japan next year."},{"label":"Watch out","text":"Not plan travelling or plan of travelling."}]', 3719);
