INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-01'), 'micro_feedback', 'A08-T29', 'to as a preposition + -ing (look forward to, object to)', 'When to use: After phrases where to is a preposition, not part of the verb.
Look for: look forward to, object to, confess to. You can test it: if a noun fits after to, use -ing.
Example: I look forward to meeting you.
Watch out: Not look forward to meet; confessed to taking, not confessed to take.', '[{"label":"When to use","text":"After phrases where to is a preposition, not part of the verb."},{"label":"Look for","text":"look forward to, object to, confess to. You can test it: if a noun fits after to, use -ing."},{"label":"Example","text":"I look forward to meeting you."},{"label":"Watch out","text":"Not look forward to meet; confessed to taking, not confessed to take."}]', 3801);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-02'), 'micro_feedback', 'A08-T31', 'be used to / be accustomed to + -ing', 'When to use: To say something is familiar or normal for someone.
Look for: be / get + used to or accustomed to + -ing or being + past participle.
Example: He is used to driving on the left.
Watch out: is used to driving (familiar) is different from used to drive (a past habit).', '[{"label":"When to use","text":"To say something is familiar or normal for someone."},{"label":"Look for","text":"be / get + used to or accustomed to + -ing or being + past participle."},{"label":"Example","text":"He is used to driving on the left."},{"label":"Watch out","text":"is used to driving (familiar) is different from used to drive (a past habit)."}]', 3802);
