INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-05'), 'micro_feedback', 'A08-T33', 'in addition to + -ing', 'When to use: To add another action, using a phrase that ends in to.
Look for: in addition to (and with a view to) followed by an action.
Example: In addition to holding weekly meetings, she sends daily updates.
Watch out: Not In addition to hold.', '[{"label":"When to use","text":"To add another action, using a phrase that ends in to."},{"label":"Look for","text":"in addition to (and with a view to) followed by an action."},{"label":"Example","text":"In addition to holding weekly meetings, she sends daily updates."},{"label":"Watch out","text":"Not In addition to hold."}]', 3805);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-06'), 'micro_feedback', 'A08-T32', 'Verb + preposition + -ing (insist on, prevent from, succeed in)', 'When to use: After verbs that need a fixed preposition before the action.
Look for: apologise for, insist on, prevent / discourage someone from, succeed in, be accused of.
Example: Heavy rain prevented us from leaving.
Watch out: Use -ing after the preposition and put not before it: apologised for not replying, not apologised for to reply.', '[{"label":"When to use","text":"After verbs that need a fixed preposition before the action."},{"label":"Look for","text":"apologise for, insist on, prevent / discourage someone from, succeed in, be accused of."},{"label":"Example","text":"Heavy rain prevented us from leaving."},{"label":"Watch out","text":"Use -ing after the preposition and put not before it: apologised for not replying, not apologised for to reply."}]', 3806);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-07'), 'micro_feedback', 'A08-T32', 'Verb + preposition + -ing (insist on, prevent from, succeed in)', 'When to use: After verbs that need a fixed preposition before the action.
