INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-16-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-16'), 'micro_feedback', 'A08-T23', 'Perfect infinitive (to have done)', 'When to use: After verbs like claim, appear, seem and is believed, when the action happened earlier.
Look for: an action that clearly came before the main verb.
Example: The castle is believed to have been built in 1200.
Watch out: Use to have + past participle for an earlier action: is believed to have been built, not is believed to be built.', '[{"label":"When to use","text":"After verbs like claim, appear, seem and is believed, when the action happened earlier."},{"label":"Look for","text":"an action that clearly came before the main verb."},{"label":"Example","text":"The castle is believed to have been built in 1200."},{"label":"Watch out","text":"Use to have + past participle for an earlier action: is believed to have been built, not is believed to be built."}]', 3816);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-17-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-17'), 'micro_feedback', 'A08-T36', 'Preposition + being + past participle', 'When to use: After a preposition, when the subject receives the action.
Look for: after, on, to and similar words + being + past participle.
Example: After being selected for the team, she trained every day.
Watch out: Not after to be selected; and after selecting means she chose someone else.', '[{"label":"When to use","text":"After a preposition, when the subject receives the action."},{"label":"Look for","text":"after, on, to and similar words + being + past participle."},{"label":"Example","text":"After being selected for the team, she trained every day."},{"label":"Watch out","text":"Not after to be selected; and after selecting means she chose someone else."}]', 3817);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-18-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-18'), 'micro_feedback', 'A08-T23', 'Perfect infinitive (to have done)', 'When to use: After verbs like claim, appear, seem and is believed, when the action happened earlier.
Look for: an action that clearly came before the main verb.
Example: The castle is believed to have been built in 1200.
Watch out: Use to have + past participle for an earlier action: is believed to have been built, not is believed to be built.', '[{"label":"When to use","text":"After verbs like claim, appear, seem and is believed, when the action happened earlier."},{"label":"Look for","text":"an action that clearly came before the main verb."},{"label":"Example","text":"The castle is believed to have been built in 1200."},{"label":"Watch out","text":"Use to have + past participle for an earlier action: is believed to have been built, not is believed to be built."}]', 3818);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-19-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-19'), 'micro_feedback', 'A08-T27', 'It is + adjective + for + person + to', 'When to use: To say how important, usual or difficult an action is for someone.
Look for: crucial, essential, unusual, important + for + person + to.
Example: It is unusual for him to miss a meeting.
Watch out: Use for and an object pronoun: for him, not of him or for he.', '[{"label":"When to use","text":"To say how important, usual or difficult an action is for someone."},{"label":"Look for","text":"crucial, essential, unusual, important + for + person + to."},{"label":"Example","text":"It is unusual for him to miss a meeting."},{"label":"Watch out","text":"Use for and an object pronoun: for him, not of him or for he."}]', 3819);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-20-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-20'), 'micro_feedback', 'A08-T26', 'Possessive + -ing (your taking, our being)', 'When to use: In formal English, when a person does the -ing action.
Look for: appreciate, unaware of and similar words followed by a person + -ing.
Example: We appreciate your taking the time to reply.
Watch out: appreciate you taking is common in everyday English, but the possessive (your) is preferred in formal writing.', '[{"label":"When to use","text":"In formal English, when a person does the -ing action."},{"label":"Look for","text":"appreciate, unaware of and similar words followed by a person + -ing."},{"label":"Example","text":"We appreciate your taking the time to reply."},{"label":"Watch out","text":"appreciate you taking is common in everyday English, but the possessive (your) is preferred in formal writing."}]', 3820);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-21-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-21'), 'micro_feedback', 'A08-T28', 'Having + past participle (Having gathered…)', 'When to use: To show that one action was completed before the next.
Look for: two actions done by the same person or group, one after the other.
Example: Having gathered the data, the team analysed it.
Watch out: The subject after the comma must be the one who did the first action: Having gathered the data, the team analysed it, not Having gathered the data, it was analysed.', '[{"label":"When to use","text":"To show that one action was completed before the next."},{"label":"Look for","text":"two actions done by the same person or group, one after the other."},{"label":"Example","text":"Having gathered the data, the team analysed it."},{"label":"Watch out","text":"The subject after the comma must be the one who did the first action: Having gathered the data, the team analysed it, not Having gathered the data, it was analysed."}]', 3821);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-22-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-22'), 'micro_feedback', 'A08-T24', 'Passive -ing and to forms (being seen, to be told)', 'When to use: When the subject receives the action rather than doing it.
Look for: avoid / dislike + being + past participle; demand / expect + to be + past participle.
Example: He wore sunglasses to avoid being seen.
Watch out: avoid seeing means you do not look; avoid being seen means others do not see you.', '[{"label":"When to use","text":"When the subject receives the action rather than doing it."},{"label":"Look for","text":"avoid / dislike + being + past participle; demand / expect + to be + past participle."},{"label":"Example","text":"He wore sunglasses to avoid being seen."},{"label":"Watch out","text":"avoid seeing means you do not look; avoid being seen means others do not see you."}]', 3822);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-08-038-23-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-08-038-23'), 'micro_feedback', 'A08-T25', 'Perfect and negative -ing forms (having done, not having done)', 'When to use: To show an action was completed earlier, often after regret, after or report.
Look for: a past action or regret; put not before having or the -ing word.
Example: He regretted not having followed the instructions.
Watch out: not usually goes first (not having followed), and the verb must keep its -ing form: not regretted not follow.', '[{"label":"When to use","text":"To show an action was completed earlier, often after regret, after or report."},{"label":"Look for","text":"a past action or regret; put not before having or the -ing word."},{"label":"Example","text":"He regretted not having followed the instructions."},{"label":"Watch out","text":"not usually goes first (not having followed), and the verb must keep its -ing form: not regretted not follow."}]', 3823);
