INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-041-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-041-01'), 'micro_feedback', 'A09-T01', 'Base verb after suggest, insist, recommend that', 'When to use: After verbs of advising, requesting or demanding (suggest, recommend, insist, demand, request, require, urge).
Look for: one of these verbs + that + subject. The next verb stays in its base form for every subject and tense.
Example: She recommended that he revise the paper.
Watch out: No -s and no past tense: that he revise, not that he revises or that he revised.', '[{"label":"When to use","text":"After verbs of advising, requesting or demanding (suggest, recommend, insist, demand, request, require, urge)."},{"label":"Look for","text":"one of these verbs + that + subject. The next verb stays in its base form for every subject and tense."},{"label":"Example","text":"She recommended that he revise the paper."},{"label":"Watch out","text":"No -s and no past tense: that he revise, not that he revises or that he revised."}]', 4101);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-041-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-041-02'), 'micro_feedback', 'A09-T02', 'Base verb after It is essential / vital that…', 'When to use: After adjectives of importance or necessity (essential, vital, crucial, imperative, necessary).
Look for: It is + one of these adjectives + that + subject.
Example: It is essential that every student have access to the library.
