INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-042-29-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-042-29'), 'micro_feedback', 'A09-T07', 'Continuous: be + -ing', 'When to use: To show that an action must be in progress at a certain time.
