INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-044-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-044-01'), 'micro_feedback', 'A09-T13', 'Wishes and blessings (God bless, Long live, Heaven forbid)', 'When to use: In fixed expressions of hope or blessing.
Look for: God / Heaven / Long + base verb.
Example: Long live the king!
Watch out: Do not add -s: God bless you, not God blesses you; Heaven forbid, not Heaven forbids.', '[{"label":"When to use","text":"In fixed expressions of hope or blessing."},{"label":"Look for","text":"God / Heaven / Long + base verb."},{"label":"Example","text":"Long live the king!"},{"label":"Watch out","text":"Do not add -s: God bless you, not God blesses you; Heaven forbid, not Heaven forbids."}]', 4401);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-044-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-044-02'), 'micro_feedback', 'A09-T15', 'Suffice it to say…', 'When to use: A formal phrase meaning ‘I will just say…’.
Look for: Suffice it to say (that) + a normal sentence.
Example: Suffice it to say that the trip did not go as planned.
Watch out: Not Suffices it to say or Suffice it say. The sentence after it uses normal tenses.', '[{"label":"When to use","text":"A formal phrase meaning ‘I will just say…’."},{"label":"Look for","text":"Suffice it to say (that) + a normal sentence."},{"label":"Example","text":"Suffice it to say that the trip did not go as planned."},{"label":"Watch out","text":"Not Suffices it to say or Suffice it say. The sentence after it uses normal tenses."}]', 4402);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-044-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-044-03'), 'micro_feedback', 'A09-T12', 'Fixed phrases (Be that as it may, Come what may, So be it)', 'When to use: These are set expressions; learn them as whole phrases.
Look for: Be that as it may = even so; Come what may = whatever happens; So be it = I accept it; Far be it from me to… = I don''t want to…
Example: Come what may, I will finish this project.
Watch out: Do not change the words: Be that as it may, not Be that is it may; Come what may, not Comes what may.', '[{"label":"When to use","text":"These are set expressions; learn them as whole phrases."},{"label":"Look for","text":"Be that as it may = even so; Come what may = whatever happens; So be it = I accept it; Far be it from me to… = I don''t want to…"},{"label":"Example","text":"Come what may, I will finish this project."},{"label":"Watch out","text":"Do not change the words: Be that as it may, not Be that is it may; Come what may, not Comes what may."}]', 4403);
