INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-044-22-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-044-22'), 'micro_feedback', 'A09-T12', 'Fixed phrases (Be that as it may, Come what may, So be it)', 'When to use: These are set expressions; learn them as whole phrases.
