INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-01'), 'micro_feedback', 'A09-T16', 'Polite conditions with Should you…', 'When to use: A formal way of saying If you… in instructions and notices.
Look for: Should + subject + base verb at the start.
Example: Should you require further help, please contact us.
Watch out: Use the base verb: Should your family need, not Should your family needs or needed.', '[{"label":"When to use","text":"A formal way of saying If you… in instructions and notices."},{"label":"Look for","text":"Should + subject + base verb at the start."},{"label":"Example","text":"Should you require further help, please contact us."},{"label":"Watch out","text":"Use the base verb: Should your family need, not Should your family needs or needed."}]', 4501);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-02'), 'micro_feedback', 'A09-T17', 'Formal requests (request that + base verb)', 'When to use: In formal notices and letters (We request that…, It is requested that…).
Look for: request that + subject + base verb, or not + base verb.
Example: It is hereby requested that visitors not bring food into the gallery.
Watch out: that you not bring, not that you do not bring; that he attend, not that he attends.', '[{"label":"When to use","text":"In formal notices and letters (We request that…, It is requested that…)."},{"label":"Look for","text":"request that + subject + base verb, or not + base verb."},{"label":"Example","text":"It is hereby requested that visitors not bring food into the gallery."},{"label":"Watch out","text":"that you not bring, not that you do not bring; that he attend, not that he attends."}]', 4502);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-03'), 'micro_feedback', 'A09-T18', 'Would you be so kind as to…?', 'When to use: A very polite way of asking someone to do something.
Look for: so kind as to + base verb.
Example: Would you be so kind as to close the window?
Watch out: Keep both as and to: not so kind that to close or so kind as close.', '[{"label":"When to use","text":"A very polite way of asking someone to do something."},{"label":"Look for","text":"so kind as to + base verb."},{"label":"Example","text":"Would you be so kind as to close the window?"},{"label":"Watch out","text":"Keep both as and to: not so kind that to close or so kind as close."}]', 4503);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-04'), 'micro_feedback', 'A09-T17', 'Formal requests (request that + base verb)', 'When to use: In formal notices and letters (We request that…, It is requested that…).
Look for: request that + subject + base verb, or not + base verb.
Example: It is hereby requested that visitors not bring food into the gallery.
