INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-05'), 'micro_feedback', 'A09-T19', 'I would appreciate it if you would…', 'When to use: A polite way of making a request.
Look for: appreciate it if + subject + would / could.
Example: We would appreciate it if you would reply by Friday.
Watch out: Keep it after appreciate: I''d appreciate it if…, not I''d appreciate if….', '[{"label":"When to use","text":"A polite way of making a request."},{"label":"Look for","text":"appreciate it if + subject + would / could."},{"label":"Example","text":"We would appreciate it if you would reply by Friday."},{"label":"Watch out","text":"Keep it after appreciate: I''d appreciate it if…, not I''d appreciate if…."}]', 4505);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-06'), 'micro_feedback', 'A09-T20', 'Were it possible for you to…', 'When to use: A formal way of saying If it were possible for you to….
Look for: Were it possible for + person + to + base verb.
Example: Were it possible for you to send the files today, we could start sooner.
Watch out: Use Were, not Was, and keep to: Were it possible for you to send, not Was it possible for you send.', '[{"label":"When to use","text":"A formal way of saying If it were possible for you to…."},{"label":"Look for","text":"Were it possible for + person + to + base verb."},{"label":"Example","text":"Were it possible for you to send the files today, we could start sooner."},{"label":"Watch out","text":"Use Were, not Was, and keep to: Were it possible for you to send, not Was it possible for you send."}]', 4506);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-09-045-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-09-045-07'), 'micro_feedback', 'A09-T21', 'on condition that', 'When to use: To give a strict condition in formal English.
Look for: on condition that + subject + verb.
Example: You may borrow the book on condition that you return it by Monday.
Watch out: The usual present tense is standard (on condition that he is present); be (that he be present) is very formal. Do not use will after it.', '[{"label":"When to use","text":"To give a strict condition in formal English."},{"label":"Look for","text":"on condition that + subject + verb."},{"label":"Example","text":"You may borrow the book on condition that you return it by Monday."},{"label":"Watch out","text":"The usual present tense is standard (on condition that he is present); be (that he be present) is very formal. Do not use will after it."}]', 4507);
