INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-046-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-046-01'), 'micro_feedback', 'A10-T01', 'Seldom / Rarely / Never + auxiliary + subject', 'When to use: To emphasise how rarely something happens, by putting the word first (formal).
Look for: Seldom, Rarely, Never or Hardly ever at the start, followed by question order.
Example: Rarely does he leave the office before seven.
Watch out: Use question order and the base verb: Rarely does he leave, not Rarely he leaves or Rarely does he leaves.', '[{"label":"When to use","text":"To emphasise how rarely something happens, by putting the word first (formal)."},{"label":"Look for","text":"Seldom, Rarely, Never or Hardly ever at the start, followed by question order."},{"label":"Example","text":"Rarely does he leave the office before seven."},{"label":"Watch out","text":"Use question order and the base verb: Rarely does he leave, not Rarely he leaves or Rarely does he leaves."}]', 4601);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-046-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-046-02'), 'micro_feedback', 'A10-T02', 'Under no circumstances / On no account + auxiliary + subject', 'When to use: To make a strong ‘never’ or ‘not at all’ statement.
Look for: Under no circumstances, On no account, At no time, In no way, By no means, Nowhere at the start.
Example: Under no circumstances should children be left alone.
Watch out: Put the auxiliary before the subject: should children be, not children should be.', '[{"label":"When to use","text":"To make a strong ‘never’ or ‘not at all’ statement."},{"label":"Look for","text":"Under no circumstances, On no account, At no time, In no way, By no means, Nowhere at the start."},{"label":"Example","text":"Under no circumstances should children be left alone."},{"label":"Watch out","text":"Put the auxiliary before the subject: should children be, not children should be."}]', 4602);
