INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-01'), 'micro_feedback', 'A10-T06', 'No sooner had… than…', 'When to use: To say one thing happened immediately after another.
Look for: No sooner + had + subject + past participle, then than.
Example: No sooner had we arrived than it started to rain.
Watch out: Use than, not when or then, and invert: No sooner had we arrived, not No sooner we had arrived.', '[{"label":"When to use","text":"To say one thing happened immediately after another."},{"label":"Look for","text":"No sooner + had + subject + past participle, then than."},{"label":"Example","text":"No sooner had we arrived than it started to rain."},{"label":"Watch out","text":"Use than, not when or then, and invert: No sooner had we arrived, not No sooner we had arrived."}]', 4701);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-02'), 'micro_feedback', 'A10-T07', 'Hardly / Scarcely / Barely had… when…', 'When to use: To say one thing happened just after another.
Look for: Hardly / Scarcely / Barely + had + subject + past participle, then when.
Example: Hardly had we left when the phone rang.
Watch out: Use when, not than: Hardly had we left when….', '[{"label":"When to use","text":"To say one thing happened just after another."},{"label":"Look for","text":"Hardly / Scarcely / Barely + had + subject + past participle, then when."},{"label":"Example","text":"Hardly had we left when the phone rang."},{"label":"Watch out","text":"Use when, not than: Hardly had we left when…."}]', 4702);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-03'), 'micro_feedback', 'A10-T08', 'Not only… but also… at the start', 'When to use: To emphasise that two things are true, starting with Not only.
Look for: Not only + auxiliary + subject + verb, then but (also).
Example: Not only did she sprain her ankle, but she also lost her phone.
Watch out: Use the base verb after did: Not only did she sprain, not Not only did she sprained or Not only she sprained.', '[{"label":"When to use","text":"To emphasise that two things are true, starting with Not only."},{"label":"Look for","text":"Not only + auxiliary + subject + verb, then but (also)."},{"label":"Example","text":"Not only did she sprain her ankle, but she also lost her phone."},{"label":"Watch out","text":"Use the base verb after did: Not only did she sprain, not Not only did she sprained or Not only she sprained."}]', 4703);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-04'), 'micro_feedback', 'A10-T09', 'Neither / Nor + auxiliary + subject', 'When to use: To add a second negative statement (I can''t swim, and neither can he).
Look for: neither or nor followed by auxiliary / modal / be + subject.
Example: She doesn''t eat meat, nor does her brother.
Watch out: Use question order and no second negative: nor is he, not nor he is or nor isn''t he.', '[{"label":"When to use","text":"To add a second negative statement (I can''t swim, and neither can he)."},{"label":"Look for","text":"neither or nor followed by auxiliary / modal / be + subject."},{"label":"Example","text":"She doesn''t eat meat, nor does her brother."},{"label":"Watch out","text":"Use question order and no second negative: nor is he, not nor he is or nor isn''t he."}]', 4704);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-05'), 'micro_feedback', 'A10-T07', 'Hardly / Scarcely / Barely had… when…', 'When to use: To say one thing happened just after another.
Look for: Hardly / Scarcely / Barely + had + subject + past participle, then when.
Example: Hardly had we left when the phone rang.
Watch out: Use when, not than: Hardly had we left when….', '[{"label":"When to use","text":"To say one thing happened just after another."},{"label":"Look for","text":"Hardly / Scarcely / Barely + had + subject + past participle, then when."},{"label":"Example","text":"Hardly had we left when the phone rang."},{"label":"Watch out","text":"Use when, not than: Hardly had we left when…."}]', 4705);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-06'), 'micro_feedback', 'A10-T10', 'Not until / Not since + inversion', 'When to use: To emphasise that something did not happen until (or has not happened since) a certain time.
Look for: Not until… or Not since… at the start; invert the main clause.
Examples: Not until he arrived did she relax. Not since 2010 has the town seen such a storm.
Watch out: Invert the main clause, not the until-part. After Not since, use the present perfect.', '[{"label":"When to use","text":"To emphasise that something did not happen until (or has not happened since) a certain time."},{"label":"Look for","text":"Not until… or Not since… at the start; invert the main clause."},{"label":"Examples","text":"Not until he arrived did she relax. Not since 2010 has the town seen such a storm."},{"label":"Watch out","text":"Invert the main clause, not the until-part. After Not since, use the present perfect."}]', 4706);
