INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-047-18-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-047-18'), 'micro_feedback', 'A10-T08', 'Not only… but also… at the start', 'When to use: To emphasise that two things are true, starting with Not only.
Look for: Not only + auxiliary + subject + verb, then but (also).
Example: Not only did she sprain her ankle, but she also lost her phone.
Watch out: Use the base verb after did: Not only did she sprain, not Not only did she sprained or Not only she sprained.', '[{"label":"When to use","text":"To emphasise that two things are true, starting with Not only."},{"label":"Look for","text":"Not only + auxiliary + subject + verb, then but (also)."},{"label":"Example","text":"Not only did she sprain her ankle, but she also lost her phone."},{"label":"Watch out","text":"Use the base verb after did: Not only did she sprain, not Not only did she sprained or Not only she sprained."}]', 4718);
