INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-048-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-048-01'), 'micro_feedback', 'A10-T12', 'Direction phrase + verb + subject (Down the hill rolled the ball)', 'When to use: To make movement more vivid, by putting the direction first.
Look for: a direction word or phrase at the start (Down…, Into…, Off…, Away…), then the verb, then a noun subject.
Example: Down the hill rolled the ball.
Watch out: Do not add did: Down the hill rolled the ball, not Down the hill did roll the ball.', '[{"label":"When to use","text":"To make movement more vivid, by putting the direction first."},{"label":"Look for","text":"a direction word or phrase at the start (Down…, Into…, Off…, Away…), then the verb, then a noun subject."},{"label":"Example","text":"Down the hill rolled the ball."},{"label":"Watch out","text":"Do not add did: Down the hill rolled the ball, not Down the hill did roll the ball."}]', 4801);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-048-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-048-02'), 'micro_feedback', 'A10-T11', 'Place phrase + verb + subject (On the hill stands a castle)', 'When to use: In descriptive writing, to put a place phrase first.
Look for: a place phrase at the start (On the shelf…, Near the door…), then the verb, then a noun subject.
Example: On the shelves sit glass jars.
Watch out: Match the verb to the subject that comes after it: sit glass jars, not sits glass jars. Do not add do / did.', '[{"label":"When to use","text":"In descriptive writing, to put a place phrase first."},{"label":"Look for","text":"a place phrase at the start (On the shelf…, Near the door…), then the verb, then a noun subject."},{"label":"Example","text":"On the shelves sit glass jars."},{"label":"Watch out","text":"Match the verb to the subject that comes after it: sit glass jars, not sits glass jars. Do not add do / did."}]', 4802);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-048-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-048-03'), 'micro_feedback', 'A10-T12', 'Direction phrase + verb + subject (Down the hill rolled the ball)', 'When to use: To make movement more vivid, by putting the direction first.
Look for: a direction word or phrase at the start (Down…, Into…, Off…, Away…), then the verb, then a noun subject.
