INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-048-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-048-04'), 'micro_feedback', 'A10-T13', 'Here comes… / There goes…', 'When to use: To point out something arriving or leaving.
Key difference: With a noun, invert: Here comes the bus. With a pronoun, do not: Here it comes.
Example: Here comes Uncle Bob.
Watch out: Here she comes, not Here comes she; and no do: not Here does come Uncle Bob.', '[{"label":"When to use","text":"To point out something arriving or leaving."},{"label":"Key difference","text":"With a noun, invert: Here comes the bus. With a pronoun, do not: Here it comes."},{"label":"Example","text":"Here comes Uncle Bob."},{"label":"Watch out","text":"Here she comes, not Here comes she; and no do: not Here does come Uncle Bob."}]', 4804);
