INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-01'), 'micro_feedback', 'A10-T15', 'Should + subject instead of If', 'When to use: A formal way of saying If you… about a possible future event.
Look for: Should + subject + base verb at the start.
Example: Should you need help, please call us.
Watch out: Do not keep if and do not add -s: Should he call, not If should he call or Should he calls.', '[{"label":"When to use","text":"A formal way of saying If you… about a possible future event."},{"label":"Look for","text":"Should + subject + base verb at the start."},{"label":"Example","text":"Should you need help, please call us."},{"label":"Watch out","text":"Do not keep if and do not add -s: Should he call, not If should he call or Should he calls."}]', 4901);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-02'), 'micro_feedback', 'A10-T18', 'Had + subject + past participle (imagined past)', 'When to use: A formal way of saying If I had….
Look for: Had + subject + past participle at the start.
Example: Had we known about the traffic, we would have left earlier.
Watch out: Do not keep if and use the past participle: Had we known, not If had we known or Had we knew.', '[{"label":"When to use","text":"A formal way of saying If I had…."},{"label":"Look for","text":"Had + subject + past participle at the start."},{"label":"Example","text":"Had we known about the traffic, we would have left earlier."},{"label":"Watch out","text":"Do not keep if and use the past participle: Had we known, not If had we known or Had we knew."}]', 4902);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-03'), 'micro_feedback', 'A10-T16', 'Were + subject + to (imagined future)', 'When to use: A formal way of saying If he/she were to….
Look for: Were + subject + to + base verb at the start.
Example: Were he to resign, the company would be in trouble.
Watch out: Keep to: Were he to resign, not Were he resign.', '[{"label":"When to use","text":"A formal way of saying If he/she were to…."},{"label":"Look for","text":"Were + subject + to + base verb at the start."},{"label":"Example","text":"Were he to resign, the company would be in trouble."},{"label":"Watch out","text":"Keep to: Were he to resign, not Were he resign."}]', 4903);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-04'), 'micro_feedback', 'A10-T15', 'Should + subject instead of If', 'When to use: A formal way of saying If you… about a possible future event.
