INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-05'), 'micro_feedback', 'A10-T18', 'Had + subject + past participle (imagined past)', 'When to use: A formal way of saying If I had….
