INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-06'), 'micro_feedback', 'A10-T19', 'Had + subject + not (negative)', 'When to use: To make the formal Had… conditional negative.
Look for: Had + subject + not + past participle.
Example: Had he not checked the brakes, there could have been an accident.
Watch out: Do not shorten it: Had he not checked, not Hadn''t he checked.', '[{"label":"When to use","text":"To make the formal Had… conditional negative."},{"label":"Look for","text":"Had + subject + not + past participle."},{"label":"Example","text":"Had he not checked the brakes, there could have been an accident."},{"label":"Watch out","text":"Do not shorten it: Had he not checked, not Hadn''t he checked."}]', 4906);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-049-07-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-049-07'), 'micro_feedback', 'A10-T17', 'Were + subject + description / Were it not for…', 'When to use: A formal way of saying If I were… or If it were not for….
Look for: Were + subject + adjective / noun / place phrase, or Were it not for + noun.
Examples: Were I in your position, I would accept. Were it not for your help, I would have failed.
