INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-050-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-050-01'), 'micro_feedback', 'A10-T21', 'So + adjective + be + subject + that', 'When to use: To emphasise the degree of something and its result (formal).
Look for: So + adjective at the start, then was / were + subject, then that.
Example: So severe were the storms that the roads were closed.
Watch out: Invert and match the verb: So severe were the storms, not So severe the storms were or So severe was the storms.', '[{"label":"When to use","text":"To emphasise the degree of something and its result (formal)."},{"label":"Look for","text":"So + adjective at the start, then was / were + subject, then that."},{"label":"Example","text":"So severe were the storms that the roads were closed."},{"label":"Watch out","text":"Invert and match the verb: So severe were the storms, not So severe the storms were or So severe was the storms."}]', 5001);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-050-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-050-02'), 'micro_feedback', 'A10-T23', 'Tired as he was… / Try as he might…', 'When to use: A formal way of saying Although…, by putting the adjective, adverb or verb first.
Look for: adjective / adverb / base verb + as or though + subject + verb.
Examples: Tired as he was, he kept working. Try as she might, she couldn''t open the jar.
Watch out: Use as or though, not although: Hard as he worked, not Hard although he worked; Try as he might, not Trying as he might.', '[{"label":"When to use","text":"A formal way of saying Although…, by putting the adjective, adverb or verb first."},{"label":"Look for","text":"adjective / adverb / base verb + as or though + subject + verb."},{"label":"Examples","text":"Tired as he was, he kept working. Try as she might, she couldn''t open the jar."},{"label":"Watch out","text":"Use as or though, not although: Hard as he worked, not Hard although he worked; Try as he might, not Trying as he might."}]', 5002);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-050-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-050-03'), 'micro_feedback', 'A10-T24', 'Past participle + be + subject (Attached to the letter were…)', 'When to use: In formal writing, to start with a past participle phrase.
Look for: Attached, Hidden, Included… at the start, then is / are / was / were + subject.
Example: Attached to the letter were two photos.
Watch out: Match be to the subject after it: were the photos, not was the photos.', '[{"label":"When to use","text":"In formal writing, to start with a past participle phrase."},{"label":"Look for","text":"Attached, Hidden, Included… at the start, then is / are / was / were + subject."},{"label":"Example","text":"Attached to the letter were two photos."},{"label":"Watch out","text":"Match be to the subject after it: were the photos, not was the photos."}]', 5003);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-050-04-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-050-04'), 'micro_feedback', 'A10-T25', '…, as does her sister (as + auxiliary + subject)', 'When to use: To say someone else does the same thing, often in formal writing.
Look for: as + do / does / did / is / have + subject.
Example: She loves music, as does her sister.
Watch out: Use an auxiliary that matches the subject: as does her sister, not as loves her sister or as do her sister. (as her sister does is also correct.)', '[{"label":"When to use","text":"To say someone else does the same thing, often in formal writing."},{"label":"Look for","text":"as + do / does / did / is / have + subject."},{"label":"Example","text":"She loves music, as does her sister."},{"label":"Watch out","text":"Use an auxiliary that matches the subject: as does her sister, not as loves her sister or as do her sister. (as her sister does is also correct.)"}]', 5004);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-10-050-05-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-10-050-05'), 'micro_feedback', 'A10-T22', 'Such was… + that', 'When to use: To emphasise how great something was and its result (formal).
Look for: Such + was / were + noun subject, then that.
Example: Such was the noise that nobody could sleep.
Watch out: No did, and use that: not Such did the noise be or Such was the noise like.', '[{"label":"When to use","text":"To emphasise how great something was and its result (formal)."},{"label":"Look for","text":"Such + was / were + noun subject, then that."},{"label":"Example","text":"Such was the noise that nobody could sleep."},{"label":"Watch out","text":"No did, and use that: not Such did the noise be or Such was the noise like."}]', 5005);
