INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-051-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-051-01'), 'micro_feedback', 'A11-T01', 'Starting with an -ing phrase (Walking home, she…)', 'When to use: To describe an action, feeling or reason connected with the subject of the main sentence.
Look for: an -ing phrase at the start, followed by a comma and the person who does that action.
Example: Walking down the trail, she admired the autumn leaves.
Watch out: The subject after the comma must be the one doing the action: Walking home, I saw a fox, not Walking home, a fox was seen.', '[{"label":"When to use","text":"To describe an action, feeling or reason connected with the subject of the main sentence."},{"label":"Look for","text":"an -ing phrase at the start, followed by a comma and the person who does that action."},{"label":"Example","text":"Walking down the trail, she admired the autumn leaves."},{"label":"Watch out","text":"The subject after the comma must be the one doing the action: Walking home, I saw a fox, not Walking home, a fox was seen."}]', 5101);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-051-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-051-02'), 'micro_feedback', 'A11-T03', 'Noun + -ing (the man playing the violin)', 'When to use: To describe a person or thing by what it is doing (short for who / which is doing).
