INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-054-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-054-01'), 'micro_feedback', 'A11-T08', 'Matching the -ing phrase to the right subject', 'When to use: Whenever a sentence starts with an -ing phrase or While / Before / After + -ing.
Look for: the noun right after the comma. Ask: can this person or thing do the action?
Example: While driving along the coast, our family spotted dolphins.
Watch out: Not While driving along the coast, dolphins were spotted: the dolphins were not driving.', '[{"label":"When to use","text":"Whenever a sentence starts with an -ing phrase or While / Before / After + -ing."},{"label":"Look for","text":"the noun right after the comma. Ask: can this person or thing do the action?"},{"label":"Example","text":"While driving along the coast, our family spotted dolphins."},{"label":"Watch out","text":"Not While driving along the coast, dolphins were spotted: the dolphins were not driving."}]', 5401);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-054-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-054-02'), 'micro_feedback', 'A11-T09', 'Matching the past participle phrase to the right subject', 'When to use: Whenever a sentence starts with a past participle phrase (Written…, Covered…, Exhausted…).
Look for: the noun right after the comma. Ask: was this the thing written, covered or exhausted?
Example: Written on a napkin, the phone number was hard to read.
Watch out: Not Written on a napkin, we could hardly read the number: we were not written on a napkin.', '[{"label":"When to use","text":"Whenever a sentence starts with a past participle phrase (Written…, Covered…, Exhausted…)."},{"label":"Look for","text":"the noun right after the comma. Ask: was this the thing written, covered or exhausted?"},{"label":"Example","text":"Written on a napkin, the phone number was hard to read."},{"label":"Watch out","text":"Not Written on a napkin, we could hardly read the number: we were not written on a napkin."}]', 5402);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-054-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-054-03'), 'micro_feedback', 'A11-T10', 'Matching the Having… phrase to the right subject', 'When to use: Whenever a sentence starts with Having + past participle.
Look for: the noun right after the comma. Ask: who completed the first action?
Example: Having finished baking, Grandma turned off the oven.
Watch out: Not Having finished the report, the computer was turned off: the computer did not finish the report.', '[{"label":"When to use","text":"Whenever a sentence starts with Having + past participle."},{"label":"Look for","text":"the noun right after the comma. Ask: who completed the first action?"},{"label":"Example","text":"Having finished baking, Grandma turned off the oven."},{"label":"Watch out","text":"Not Having finished the report, the computer was turned off: the computer did not finish the report."}]', 5403);
