INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-055-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-055-01'), 'micro_feedback', 'A11-T11', 'While / When / Before / After / Though + -ing', 'When to use: To shorten a clause when both parts have the same subject (While I was waiting → While waiting).
Look for: one of these words with no subject after it, then an -ing form.
Example: While waiting for the bus, she read a book.
Watch out: Use -ing after the linking word: While waiting, not While wait or While waited.', '[{"label":"When to use","text":"To shorten a clause when both parts have the same subject (While I was waiting → While waiting)."},{"label":"Look for","text":"one of these words with no subject after it, then an -ing form."},{"label":"Example","text":"While waiting for the bus, she read a book."},{"label":"Watch out","text":"Use -ing after the linking word: While waiting, not While wait or While waited."}]', 5501);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-11-055-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-11-055-02'), 'micro_feedback', 'A11-T12', 'When / Once / Unless / Although + past participle', 'When to use: To shorten a clause with a passive meaning (Once they are washed → Once washed).
Look for: one of these words with no subject after it, where the subject receives the action.
Example: Once washed, the vegetables are ready to cook.
Watch out: Use the past participle when the subject is affected: Unless stored in a cool place, not Unless storing in a cool place.', '[{"label":"When to use","text":"To shorten a clause with a passive meaning (Once they are washed → Once washed)."},{"label":"Look for","text":"one of these words with no subject after it, where the subject receives the action."},{"label":"Example","text":"Once washed, the vegetables are ready to cook."},{"label":"Watch out","text":"Use the past participle when the subject is affected: Unless stored in a cool place, not Unless storing in a cool place."}]', 5502);
