INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-056-01-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-056-01'), 'micro_feedback', 'A12-T04', 'Verb + for (apply for, apologise for, blame for, search for)', 'When to use: With verbs about reasons, seeking, regret and responsibility.
Example: He apologised for arriving late.
Watch out: blamed him for the mistake, not about. apply for a job, but apply to a company.', '[{"label":"When to use","text":"With verbs about reasons, seeking, regret and responsibility."},{"label":"Example","text":"He apologised for arriving late."},{"label":"Watch out","text":"blamed him for the mistake, not about. apply for a job, but apply to a company."}]', 5601);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-056-02-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-056-02'), 'micro_feedback', 'A12-T03', 'Verb + on (rely on, depend on, insist on, congratulate on)', 'When to use: With verbs about trust, agreement, firm demands and praise.
Example: She congratulated him on passing the exam.
Watch out: congratulated him on, not for; insisted on paying, not insisted to pay.', '[{"label":"When to use","text":"With verbs about trust, agreement, firm demands and praise."},{"label":"Example","text":"She congratulated him on passing the exam."},{"label":"Watch out","text":"congratulated him on, not for; insisted on paying, not insisted to pay."}]', 5602);
INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-056-03-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-056-03'), 'micro_feedback', 'A12-T08', 'Verb + into (divide into, split into, convert into)', 'When to use: When something is separated into parts or changed into something else.
Example: The teacher divided the class into four groups.
Watch out: divided into six pieces, not divided in or divided to six pieces.', '[{"label":"When to use","text":"When something is separated into parts or changed into something else."},{"label":"Example","text":"The teacher divided the class into four groups."},{"label":"Watch out","text":"divided into six pieces, not divided in or divided to six pieces."}]', 5603);
