INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-056-06-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-056-06'), 'micro_feedback', 'A12-T01', 'Verb + of (accuse of, approve of, consist of, dream of)', 'When to use: With verbs that always take of before the person, thing or action.
