INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-059-19-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-059-19'), 'micro_feedback', 'A12-T25', 'remember / forget / regret / stop / try + -ing or to', 'When to use: When the meaning depends on which form you choose.
Key difference: remember / forget + -ing = a past memory; + to = a task to do. stop + -ing = quit; + to = pause in order to. try to = make an effort.
Examples: I remember leaving my umbrella on the train. Please remember to lock the door.
Watch out: stop smoking means quit; stop to smoke means pause in order to smoke.', '[{"label":"When to use","text":"When the meaning depends on which form you choose."},{"label":"Key difference","text":"remember / forget + -ing = a past memory; + to = a task to do. stop + -ing = quit; + to = pause in order to. try to = make an effort."},{"label":"Examples","text":"I remember leaving my umbrella on the train. Please remember to lock the door."},{"label":"Watch out","text":"stop smoking means quit; stop to smoke means pause in order to smoke."}]', 5919);
