INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-060-19-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-060-19'), 'micro_feedback', 'A12-T31', 'in spite of, regardless of, contrary to', 'When to use: Fixed phrases for contrast, followed by a noun or -ing.
