INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-060-20-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-060-20'), 'micro_feedback', 'A12-T37', 'at hand (the task at hand)', 'When to use: To mean the thing you are dealing with now, or something close by.
