INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-060-22-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-060-22'), 'micro_feedback', 'A12-T33', 'Reason phrases (due to, on account of, in light of, by virtue of)', 'When to use: Fixed phrases that give a cause or reason.
