INSERT INTO feedback_items (feedback_code, test_id, test_part_id, question_id, kind, type_ref, heading, body, fields_json, sort_order) VALUES ('01-01-12-060-25-00', 1, 1, (SELECT id FROM questions WHERE question_code = '01-01-12-060-25'), 'micro_feedback', 'A12-T34', 'according to, in addition to, in response to, in accordance with', 'When to use: Fixed phrases for sources, extra points, replies and following rules.
